quests[9198] = { id = 9198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Thorium Tube", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order EN-558:\n\n14 Thorium Tubes.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", sourceObjective = "Deliver 14 Thorium Tubes and the Craftsman's Writ - Thorium Tube - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "Thorium tubes? Gee, thanks.\n\n<Packmaster Stonebruiser throws the stack of Thorium tubes into a large pile of assorted junk.>", sourceObjectiveStatus = "unverified-source-field" }
quests[9199] = { id = 9199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Juju", description = "The corpses of trolls buried inside the Amani Catacombs have been rising from the dead! I want you to go there and bring back proof of their final demise. Some of these mummy trolls, and their living counterparts, carry juju; glowing objects that house an unknown power source.  It's probably what is animating them!\n\nThe catacombs lie within Sungraze Peak, directly to the east. I am told that the easiest way in lies on the north face of the mountain. See to it, {class}!", sourceObjective = "Collect 8 Troll Juju and return them to Deathstalker Maltendis at Tranquillien in the Ghostlands.", progress = "I don't have to remind you that we can ill afford this trouble with the troll dead rising in our very backyard! We have enough trouble with Deatholme to the south!", completion = "Mummies being raised by troll priests... clever! The Shadowpine trolls must be trying to bolster their numbers through necromantic means. I'd wager that these oracles were using the juju in their reanimation ritual.\n\nOnce again you perform your duty as befits a {class} of your growing reputation. Take this with our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[9200] = { id = 9200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Major Mana Potion", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-473:\n\n10 Major Mana Potions.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", sourceObjective = "Deliver 10 Major Mana Potions and the Craftsman's Writ - Major Mana Potion - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "The utility of these should go without saying.", sourceObjectiveStatus = "unverified-source-field" }
quests[9201] = { id = 9201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Greater Arcane Protection Potion", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-1420:\n\n15 Greater Arcane Protection Potions.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", sourceObjective = "Deliver 15 Greater Arcane Protection Potions and the Craftsman's Writ - Greater Arcane Protection Potion - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "<Packmaster Stonebruiser pops open one of the greater arcane protection potions and take a swig.>\n\nWOOT! These pack a kick, baby! A kick I say!", sourceObjectiveStatus = "unverified-source-field" }
quests[9202] = { id = 9202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Major Healing Potion", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-169110:\n\n20 Major Healing Potions.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", sourceObjective = "Deliver 20 Major Healing Potions and the Craftsman's Writ - Major Healing Potion - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "Do you know what the troops on the front lines call these? Priests in a bottle...\n\n<Packmaster Stonebruiser sings.>\n\n\"I'm your priest in a bott-le baby... you gotta drink me the right way...\"\n\nWhat's the matter sonny? It's a very popular song around these parts.", sourceObjectiveStatus = "unverified-source-field" }
quests[9203] = { id = 9203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Flask of Petrification", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-90:\n\n1 Flask of Petrification.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", sourceObjective = "Deliver 1 Flask of Petrification and the Craftsman's Writ - Flask of Petrification - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[9204] = { id = 9204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Stonescale Eel", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-5:\n\n40 Stonescale Eel.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", sourceObjective = "Deliver 40 Stonescale Eel and the Craftsman's Writ - Stonescale Eel - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "You could have used this for something else, but you didn't, did you? No use crying about it now, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9205] = { id = 9205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Plated Armorfish", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-12:\n\n30 Plated Armorfish.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", sourceObjective = "Deliver 30 Plated Armorfish and the Craftsman's Writ - Plated Armorfish - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "You really don't know what these are for?\n\n<Packmaster Stonebruiser laughs.>\n\nLike I'm going to tell you!", sourceObjectiveStatus = "unverified-source-field" }
quests[9206] = { id = 9206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Lightning Eel", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-9:\n\n30 Lightning Eel.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", sourceObjective = "Deliver 30 Lightning Eel and the Craftsman's Writ - Lightning Eel - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "These make the best eel rolls in the world. That's right - IN THE WORLD.", sourceObjectiveStatus = "unverified-source-field" }
quests[9207] = { id = 9207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underlight Ore Samples", description = "I was sent here from the Sanctum of the Sun to collect some ore samples, but the gnolls have overrun the place! It's going to be my head on a platter if I don't get those samples to the magister soon. Maybe you could help, {class}?\n\nYou can find the ore in the tin and copper veins here, and the gnolls are carrying it around, too. When you have enough, take it to Magister Quallestis at the Sanctum of the Sun directly to the east. Go across the Dead Scar and you'll find the sanctum just south of Sungraze Peak.", sourceObjective = "Collect 6 Underlight Ore and deliver them to Magister Quallestis at the Sanctum of the Sun in the Ghostlands.", progress = "How may I help you, {class}?", completion = "My apprentice was unable to take care of this herself?  I shall have a word with her when she returns then, gnolls or not.  Speaking of which, why didn't she return with you?\n\n<The magister sighs.>\n\nThat one is a handful, and is going to be quite a challenge to properly train.  Thank you, {class}, for bringing these samples to me.  We are hoping that we can uncover some special property from them that will help in the fight against the Scourge.\n\nPlease take this coin as a token of my appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[9208] = { id = 9208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savage Guard - Arcanum of Protection", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", sourceObjective = "Zanza the Restless in Zul'Gurub wants an Arcanum of Protection.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard.", sourceObjectiveStatus = "unverified-source-field" }
quests[9209] = { id = 9209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savage Guard - Arcanum of Rapidity", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", sourceObjective = "Zanza the Restless in Zul'Gurub wants an Arcanum of Rapidity.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard.", sourceObjectiveStatus = "unverified-source-field" }
quests[9210] = { id = 9210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savage Guard - Arcanum of Focus", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", sourceObjective = "Zanza the Restless in Zul'Gurub wants an Arcanum of Focus.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard.", sourceObjectiveStatus = "unverified-source-field" }
quests[9211] = { id = 9211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ice Guard", description = "Ah, the Ice Guard. It is a thin sheen of protective magic that covers certain pieces of equipment. Those that do battle with creatures of frost and ice will gain increased protection from their attacks by using the Ice Guard.\n\nAs with all things the Wrathcaster creates, there is a price - a price that I will not lower, regardless of how much you whimper. Interested?", sourceObjective = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.", progress = "If it were not for these Argent Dawn guards, you would be a stain upon this floor.", completion = "<Mataus pockets the gold.>\n\nEnjoy the repair costs, {race}. Naxxramas is 'unkind' to the uninitiated.", sourceObjectiveStatus = "unverified-source-field" }
quests[9212] = { id = 9212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from the Catacombs", description = "These trolls ambushed me and have been keeping me in this cage.  I think they're planning to sacrifice me!  Help me get out of here!\n\nThe lock on the cage isn't that complex... I just can't get to it from this side.  Please escort me back to the Farstrider Enclave.  I'm sure Captain Helios will reward you, and you'll have my undying gratitude!", sourceObjective = "Escort Ranger Lilatha to Captain Helios at Farstrider Enclave in the Ghostlands.", progress = "You're the one that rescued my ranger?", completion = "You're quite the hero, {class}, to get her out of there alive.  I suppose we'll have to mount an offensive to clear out those catacombs too.  As if we didn't have enough trouble with the living trolls!\n\nYou've done a great thing today, I should reward you.  Take your pick from any of these.", sourceObjectiveStatus = "unverified-source-field" }
quests[9213] = { id = 9213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Guard", description = "A creation of genius! Much like the Ice Guard, the Shadow Guard employs a thin sheen of protective magic that covers certain pieces of equipment. And like the Ice Guard, the Shadow Guard is going to cost you a good amount of money.\n\n<Mataus holds his hand out and rubs his fingers together.>\n\nInterested?", sourceObjective = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.", progress = "<Mataus yawns.>\n\nBe gone, insect, lest you have something for me.", completion = "<Mataus stuffs the gold into his robe.>\n\nWhat are you still standing around for, {race}? Our business is done.", sourceObjectiveStatus = "unverified-source-field" }
quests[9214] = { id = 9214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowpine Weaponry", description = "{class}, I want you to kill as many Shadowpine trolls as you can. We need their numbers greatly reduced before we can shift our attention toward Deatholme. And while you're at it, we might as well kill two birds with one stone, so bring me back a load of their weapons. Better that they not go to waste, and we can use them in the fight against the Scourge.\n\nHit their camps hard to the east and the south at Zeb'Tela and Zeb'Nowa.", sourceObjective = "Collect 3 Headhunter Axes, 3 Shadowcaster Maces, 3 Catlord Claws and 3 Hexxer Staves. Return them to Captain Helios at Farstrider Enclave in the Ghostlands.", progress = "Have those weapons yet? With the Shadowpine numbers decimated we'll finally be able to turn our attention to the fight against the Scourge.", completion = "I'll immediately send a few rangers out to survey the damage that you wreaked upon the Shadowpine trolls. I've no doubt that we'll be able to mop up after your offensive and launch an attack on the Scourge soon if these weapons are any indication of your success.\n\nHere, I want you to take this coin in payment. It's burning a hole in my pouch anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[9215] = { id = 9215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me Kel'gash's Head!", description = "WANTED: Bring the head of Kel'gash the Wicked, chieftain of the Shadowpine trolls, to Captain Helios. No questions asked. Kel'gash is known to dwell somewhere to the south in Zeb'Nowa.\n\n\n\nREWARD: Yes, but no advances!", sourceObjective = "Return the Head of Kel'gash the Wicked to Captain Helios at the Farstrider Enclave in the Ghostlands.", progress = "What is that awful smell?", completion = "Ah, Kel'gash's head is what smelled so bad. That's a nice piece of work there, {class}!\n\nWith their chieftain dead, the Shadowpine trolls should be in total disarray. Combined with your recent efforts to decimate their numbers, this should be the perfect opportunity to launch our counter-offensive against them and wipe them out for good.\n\nYou have my thanks, {name}. Might I interest you in one of these?", sourceObjectiveStatus = "unverified-source-field" }
quests[9216] = { id = 9216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotting Hearts", description = "I hear the Amani trolls eat their enemies' hearts to steal their strength.  They might just be on to something, {name}.  With the proper treatment, the hearts of the unliving can produce potent elixirs.\n\nHunt down the zombies that roam the Dead Scar and bring me their hearts.  I'll show you the kind of enhancement we can perform to your physical prowess against the undead.", sourceObjective = "Bring back 10 Rotting Hearts to Magistrix Aminel in Tranquillien.", progress = "Do you have the zombie hearts I requested, {name}?", completion = "Take this draught, {name}.  After you drink it, your physical strength against the Scourge will receive a boost. If you need more than this sample bring me more hearts.", sourceObjectiveStatus = "unverified-source-field" }
quests[9217] = { id = 9217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Rotting Hearts", progress = "You've brought more ghoul hearts?  I can use as many as you can collect, {name}.", completion = "This will provide you with greater power against the Scourge.   Bring more hearts if you find them, {name}." }
quests[9218] = { id = 9218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinal Dust", description = "The dark energy that flows through the bodies of reanimated skeletons tends to accumulate primarily in their spine.  I've discovered a method of instilling this energy into a potion that boosts our magical abilities against the undead.\n\nBring me some spinal dust and I'll be glad to provide you with a sample.  You'll find an ample number of skeletons wandering the Dead Scar, west of here.", sourceObjective = "Bring back 10 Spinal Dusts to Magistrix Aminel in Tranquillien.", progress = "Do you have the samples I requested, {name}?", completion = "Take this, {name}.  You'll feel the difference immediately!\n\nFeel free to bring more spinal dust; I can use as much of it as you can provide.  Side effects?  You might start feeling your joints acting up a bit.  Nothing permanent, I assure you!", sourceObjectiveStatus = "unverified-source-field" }
quests[9219] = { id = 9219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Spinal Dust", progress = "You've procured more spinal dust?  I can use as much of it as you bring me.", completion = "This dust is as potent as ever, {name}.  Keep bringing it to me if you're in need to boost your magical powers against the Scourge." }
quests[9220] = { id = 9220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on Deatholme", description = "If you seek to aid our cause there is no better place to start than here and no better time to do it than now.\n\nBy rebuilding the Sanctum of the Sun we've raised a banner of defiance in front of our enemy's seat of power: Deatholme.\n\nGo forth and fight the hordes of undead that inhabit the vile Scourge fortress.", sourceObjective = "Slay 5 Eyes of Dar'khan, 6 Nerubis Centurions and 6 Wailers in Deatholme and return to Magister Idonis at the Sanctum of the Sun in the Ghostlands.", progress = "Have you returned from Deatholme victorious, {name}?", completion = "The Scourge has felt our wrath, {name}.  It won't be long before their cursed citadel lies in ruins.\n\nWith their numbers weakened, it is time to launch an attack on more strategic targets.", sourceObjectiveStatus = "unverified-source-field" }
quests[9221] = { id = 9221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", sourceObjective = "For 30 Insignias of the Dawn and 30 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", sourceObjectiveStatus = "unverified-source-field" }
quests[9222] = { id = 9222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", sourceObjective = "For 110 Insignias of the Dawn and 110 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", sourceObjectiveStatus = "unverified-source-field" }
quests[9223] = { id = 9223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with a fairly prohibitive surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", sourceObjective = "For 20 Insignias of the Dawn and 20 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9224] = { id = 9224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", sourceObjective = "For 75 Insignias of the Dawn and 75 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", sourceObjectiveStatus = "unverified-source-field" }
quests[9225] = { id = 9225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; epic purchases made at revered reputation with the Dawn are still quite expensive. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", sourceObjective = "For 45 Insignias of the Dawn and 45 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9226] = { id = 9226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those revered amongst the Dawn are priced quite reasonably. I encourage you to make a purchase!", sourceObjective = "For 7 Insignias of the Dawn and 7 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9227] = { id = 9227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those exalted amongst the Dawn are discounted. I encourage you to make a purchase!", sourceObjective = "For 6 Insignias of the Dawn and 6 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9228] = { id = 9228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nThose exalted amongst the Dawn receive our greatest discounts! I encourage you to make a purchase.", sourceObjective = "For 27 Insignias of the Dawn and 27 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9229] = { id = 9229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Ramaladni", description = "Ramaladni was a warrior of the Brotherhood - a pupil of Highlord Mograine before the Dawn even existed! When news of Mograine's death reached him, hatred and anger took over.\n\nUnderstand this, {name}, when rage and retribution take the reins, a man ceases to be a man. The man personifies the emotions that control him instead. And so it would be that Ramaladni, the spirit of retribution, would enter Naxxramas to exact vengeance... and never return.\n\nEnter Naxxramas and find what became of Ramaladni.", sourceObjective = "Enter Naxxramas and uncover the Fate of Ramaladni.", progress = "Any news of Ramaladni?", completion = "It is his ring! But it is destroyed. No other evidence of Ramaladni was found?\n\n<Korfax grimaces.>\n\nThis does not bode well for Ramaladni. The ring, however... it might be salvageable.", sourceObjectiveStatus = "unverified-source-field" }
quests[9230] = { id = 9230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramaladni's Icy Grasp", description = "Fixing this band may prove to be quite challenging, {name}. You see, it was made from the very runes that form inside Scourge structures - like Naxxramas. Additional materials are also required but your main concern should be getting those frozen runes. Bring me what I need and I will restore the ring to its former glory.", sourceObjective = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 1 Frozen Rune, 1 Blue Sapphire and 1 Arcanite Bar.", progress = "Frozen runes could probably be found inside Naxxramas.", completion = "Ramaladni himself couldn't have done better! Here is the ring, as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[9232] = { id = 9232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Song I Know...", description = "You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?\n\n<Wilhelm sighs.>\n\nBah, what choice do I got? You're the best I can do; I may as well help you.\n\nOmarion left me with one recipe. It's the only song I know... I can make a few variations of these pants; you just gotta supply the materials.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires and 30 gold pieces.", progress = "You haven't run into Omarion, have you?", completion = "<Wilhelm wipes the sweat from his brow.>\n\nThat's some hard work! Enjoy the pants, {class}. At least you'll die in a clean pair now.", sourceObjectiveStatus = "unverified-source-field" }
quests[9233] = { id = 9233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omarion's Handbook", description = "Wilhelm,\n\nIf you are reading this, I have perished - finally. I want you to know that my dying thoughts revolved around you and your ineptitude when it comes to tradeskills. Unfortunately, the bearer of this handbook is in even worse shape than you in regards to crafting.\n\nAbout the book: These are the rest of my recipes. Make the bearer of this book whatever they request. I'm sure you will charge a hefty fee for your services because you are, after all, a bastard.\n\nIn Disdain,\n\nOmarion", sourceObjective = "Take Omarion's Handbook to Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Is that what I think it is?\n\n<Wilhelm appears to be drooling.>", completion = "He musta really been off his rocker when he wrote this! Omarion and I - we were thick as thieves!\n\nAnyhow, this certainly opens up some new possibilities, {name}. I am now able to craft more items - for a small fee and material charges, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[9234] = { id = 9234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icebane Gauntlets", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create Icebane gauntlets. All you need to do is bring me the materials and pay a small crafting fee.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essences of Water and 200 gold.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!", sourceObjectiveStatus = "unverified-source-field" }
quests[9235] = { id = 9235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icebane Bracers", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers. All you need to do is bring me the materials and pay a small crafting fee.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essence of Water and 200 gold.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!", sourceObjectiveStatus = "unverified-source-field" }
quests[9236] = { id = 9236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icebane Breastplate", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create an Icebane breastplate. All you need to do is bring me the materials and pay a small crafting fee.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 16 Thorium Bars, 2 Arcanite Bars, 4 Essence of Water and 300 gold. You will also need to be of Exalted reputation with the Argent Dawn.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!", sourceObjectiveStatus = "unverified-source-field" }
quests[9237] = { id = 9237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glacial Cloak", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create a Glacial cloak. All you need to do is bring me the materials and pay a small crafting fee.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 4 Bolts of Runecloth, 2 Essences of Water, 4 Ironweb Spider Silks and 200 gold. You must also be of Exalted reputation with the Argent Dawn.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!", sourceObjectiveStatus = "unverified-source-field" }
quests[9238] = { id = 9238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glacial Wrists", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial wrists. All you need to do is bring me the materials and pay a small crafting fee.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 2 Bolts of Runecloth, 2 Essences of Water, 2 Ironweb Spider Silks and 200 gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9239] = { id = 9239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glacial Gloves", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial gloves. All you need to do is bring me the materials and pay a small crafting fee.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 4 Bolts of Runecloth, 4 Essences of Water, 2 Ironweb Spider Silks and 200 gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9240] = { id = 9240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glacial Vest", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create a Glacial vest. All you need to do is bring me the materials and pay a small crafting fee.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 8 Bolts of Runecloth, 6 Essences of Water, 4 Ironweb Spider Silks and 300 gold. You must also be of Exalted reputation with the Argent Dawn.", sourceObjectiveStatus = "unverified-source-field" }
quests[9241] = { id = 9241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polar Bracers", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create Polar bracers. All you need to do is bring me the materials and pay a small crafting fee.", sourceObjective = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 12 Enchanted Leather, 3 Essence of Water, 3 Cured Rugged Hides and 200 gold.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!", sourceObjectiveStatus = "unverified-source-field" }
