quests[9264] = { id = 9264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Thunder Bluff", description = "The Scourge is camped upon our very doorstep; we cannot remain idle! Surely you will step up to defend Thunder Bluff from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", sourceObjective = "Collect three Dim Necrotic Stones from the Scourge outside Thunder Bluff and investigate the glowing runic circles nearby their encampment.", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service.", sourceObjectiveStatus = "unverified-source-field" }
quests[9265] = { id = 9265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of the Undercity", description = "The Scourge is camped upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Undercity from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", sourceObjective = "Collect three Dim Necrotic Stones from the Scourge outside the Undercity and investigate the glowing runic circles nearby their encampment.", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service.", sourceObjectiveStatus = "unverified-source-field" }
quests[9266] = { id = 9266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Amends", progress = "You must've done something really bad to us or our friends, {name}.  At any rate, I'm here to offer you a way to get our good graces back.\n\nAs you know, Winterspring is quite cold.  With so many of us goblins coming from other cities, we could use a hand keeping warm.  Bring me some runecloth and coal and I'll put in the good word for ya.  Be warned though, our enemies are not going to take kindly to your helping us.", completion = "Thank you, {name}.  You're on a quick path to redeeming yourself with our fair town." }
quests[9267] = { id = 9267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending Old Wounds", progress = "You'd better think twice before setting foot in Ratchet, {name}!  Word's been getting around of your dirty deeds.\n\nYou're in luck though, a ship just arrived with many wounded from an encounter with the Bloodsail Buccaneers.  This is your chance to prove you're not a complete scoundrel.  Lend us a hand by bringing linen cloth for bandages and empty vials for potions.", completion = "I'm happy you're seeing the error of your ways, {name}.  Keep the supplies coming; we're not going to forget about you so easily, mister!" }
quests[9268] = { id = 9268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War at Sea", progress = "You seek to befriend the goblins of Tanaris once again, {name}?  We're in need of materials for sails and guns to fight off our old enemies, the Bloodsail Buccaneers.  Bring me mageweave and strong flux and we'll be on our way to pardoning your trespasses.", completion = "Keep it coming, {name}.  Us goblins don't forget that easily!" }
quests[9269] = { id = 9269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", sourceObjective = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[9270] = { id = 9270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", sourceObjective = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", progress = "I must not interfere, {race}.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice...", sourceObjectiveStatus = "unverified-source-field" }
quests[9271] = { id = 9271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", sourceObjective = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", progress = "I must not interfere, {race}.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice...", sourceObjectiveStatus = "unverified-source-field" }
quests[9272] = { id = 9272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressing the Part", sourceObjective = "Yarrr... if ye be keen on enjoying the company of us experienced sea dogs, you'd best belay dressing like a blaggard!  Here, put on something proper 'fore I keelhaul yer hide.\n\nThese'll fit ye better than they ever fit that old dog, Red-Eyed Ben.  Lost him in a devil of a storm at sea.\n\nWear 'em with pride, mate!", sourceObjectiveStatus = "unverified-source-field" }
quests[9273] = { id = 9273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeem iCoke Prize Voucher" }
quests[9274] = { id = 9274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Drowned", description = "The lake to the north has been haunted by the ghosts of my ancestors for as long as I can remember, {name}.  The poor souls were victims of a tragic incident in which scores of them drowned at the bottom of the lake.\n\nThe details of the event are mostly forgotten, but their haunting cries serve as a constant reminder of their curse.\n\nIf you're up to the task, I want you to go to the lake and put an end to their suffering, {name}.  You will have my gratitude as well as theirs... I'm sure.", sourceObjective = "Ranger Krenn'an, at the Farstrider Enclave in the Ghostlands, wants you to kill 8 Vengeful Apparitions and 8 Ravening Apparitions in the nearby lake.", completion = "I appreciate your help, {name}.  It pains me to see the spirits of my ancestors in their pitiful state.  May they finally get the rest they deserve.", sourceObjectiveStatus = "unverified-source-field" }
quests[9275] = { id = 9275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Dash of Seasoning", description = "I'm on loan to the Farstriders in an attempt to help with their troll difficulties. I believe that I have a solution to their problem.\n\nAt my disposal are a number of potent poisons. The trolls, as you know, are living creatures and therefore must eat. If we combine my poison with their food... well, I'm sure that the results will be entertaining!\n\nCare to help rid us of the Shadowpine trolls at Zeb'Nowa to the south? The camp straddles both the north and south sides of the road to Zul'Aman.", sourceObjective = "Poison the Troll foodstuff at the camps in Zeb'Nowa and then return to Apothecary Venustus at the Farstrider Enclave in the Ghostlands.", completion = "Ah, excellent! I knew that a {race}-delivery system would make for the most efficient application of the poison. With any luck the Shadowpine trolls will get fat on it before keeling over. That should get them off of the backs of the Farstriders, and me back to Tranquillien.\n\nIt has been a pleasure working with you, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9276] = { id = 9276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Zeb'Tela", description = "Our resources are spread pretty thin here, {class}, so your help is going to be invaluable.  The captain has tasked me with overseeing the harassment of the local Shadowpine troll camps. We have a policy of keeping them off balance until the day when we can launch a brutal offensive to wipe them out.\n\nUntil then, we need all of the volunteers that we can get so that those Shadowpine troll numbers are decreased.\n\nThink you could head east to Zeb'Tela and hurt them a little?", sourceObjective = "Kill 8 Shadowpine Shadowcasters and 8 Shadowpine Headhunters, and return to Farstrider Solanna at Farstrider Enclave in the Ghostlands.", progress = "How are you doing with the attack on Zeb'Tela?", completion = "Good, good! You handled that very well! Let's see if you're up to something a little more difficult now.", sourceObjectiveStatus = "unverified-source-field" }
quests[9277] = { id = 9277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Zeb'Nowa", description = "Time for something a little more challenging. Zeb'Nowa, to the south, is where the more powerful Shadowpine trolls make their home. In our continuing effort to keep the troll numbers to a minimum I'm dispatching you to go down there and assail them by whatever means you have at your disposal.\n\nWhat do you say, {name}? Ready to deal with some more trolls?", sourceObjective = "Kill 10 Shadowpine Catlords and 10 Shadowpine Hexxers, and return to Farstrider Solanna at the Farstrider Enclave in the Ghostlands.", completion = "Unbelievable! You really should talk to the captain about joining up as a Farstrider.\n\nAlright, {name}, you've given us the breathing room that we need to continue building up our forces here. Actually, by your account there aren't many of those trolls left at all! Maybe now we can join with Tranquillien and attack Deatholme?\n\nI think you've earned a little something. Take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[9278] = { id = 9278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Jaeleil in Azure Watch.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", sourceObjective = "Bring the Azure Watch Gift Voucher to Jaeleil in Azure Watch.", progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[9279] = { id = 9279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Survived!", description = "Nevermind my injuries, <brother/sister>. It's a miracle that any of us are alive!\n\nIt didn't look like you'd pull through; you've been in suspension for weeks.\n\nSomething happened and the Exodar crashed. Many have died.\n\nBut I'm relieved that you are alive, {name}. With you leading our efforts, I'm sure we'll get to safety soon! Proenitus asked me to send you to him when you awoke. He's waiting for you at the bottom of the hill. Just follow the path southwest.", sourceObjective = "Speak with Proenitus at the Crash Site in Ammen Vale.", completion = "{name}, by my eternal soul, it is good to see you!  I don't know why the Exodar crashed.  Only those of us that were in this part of the ship remain.\n\nThere's not much time if we're to save everyone that we can!", sourceObjectiveStatus = "unverified-source-field" }
quests[9280] = { id = 9280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenishing the Healing Crystals", description = "Our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!\n\nUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.\n\nThe moths can be found in many places around the vale, but they are mostly concentrated in the northwest.", sourceObjective = "Acquire 8 Vials of Moth Blood from the nearby Vale Moths and give them to Proenitus at the Crash Site in Ammen Vale.", progress = "{name}, have you harvested the necessary moth blood for the healing crystals yet?  With survivors scattered all over the vale, time is of the essence!", completion = "Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the {race} way.  However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[9281] = { id = 9281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Way", description = "Magister Kaendris sent me down here to clear the area of any hostile wildlife.  Once this area is secured, the magisters plan to turn it into some sort of advance outpost against the Scourge.\n\nNow if there's one thing I've learned as an apprentice it's to delegate responsibility - especially in matters that endanger one's life!\n\nIf you're interested, I'll pay you well to kill the greater spindlewebs and ghostclaw ravagers to the west and south of here.", sourceObjective = "Apprentice Vor'el at Andilien Estate in the Ghostlands wants you to slay 10 Greater Spindlewebs and 10 Ghostclaw Ravagers.", completion = "Thanks for giving me a hand, {name}.  I was dreading the thought of venturing into the woods this close to Deatholme.", sourceObjectiveStatus = "unverified-source-field" }
quests[9282] = { id = 9282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farstrider Enclave", description = "Magisters and Farstriders may not see eye to eye all the time, {name}.  When it comes to Dar'Khan, however, we're all in agreement that a way must be found to defeat him and his legions.\n\nRanger Vynna, at the Farstrider Enclave northeast of here, has come across important information regarding our enemy.  Speak to her and see if you can be of assistance.", sourceObjective = "Magister Kaendris, at the Sanctum of the Sun, wants you to talk to Ranger Vynna at the Farstrider Enclave in the Ghostlands.", completion = "Kaendris sent you?  I might have a task for you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9283] = { id = 9283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Survivors!", description = "The healing crystals are replenished, but that is not the only way we can help the injured. All draenei can tap the gift of the Naaru to heal. You must use this ability to heal one of the crash survivors.\n\nYou'll find most of the survivors in the areas to the west and northwest, but the crash scattered us all over the vale.\n\nThe survivors have suffered from exposure to the irradiated power crystals, so you should be able to find them by the red glow that surround them.\n\nYou must save them, {name}.", sourceObjective = "Use your Gift of the Naaru ability on one of the Draenei Survivors spread throughout Ammen Vale, then return to Zalduun at the Crash Site in Ammen Vale.", completion = "The Light be praised! You've done what only a true hero could have done, {name}! The {race} you saved owes their continued life to your selflessness!\n\nPlease, take this supply pouch. You look like you can use it more than I.", sourceObjectiveStatus = "unverified-source-field" }
quests[9284] = { id = 9284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aldor Faction Test" }
quests[9285] = { id = 9285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consortium Faction Test" }
quests[9286] = { id = 9286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scryers Faction Test" }
quests[9287] = { id = 9287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paladin Training", sourceObjective = "I am heartened by your initiative to speak with me.  In the past I was responsible for the training of young paladins as they entered our order.  This is a duty and privilege that I humbly take up once more.  Your name has been mentioned as one who seeks to do good in the name of the Light.  It would be my honor to guide you in your first steps as a {class}.\n\nShall we begin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9288] = { id = 9288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter Training", sourceObjective = "I'm glad that you have come to me.  For quite some time now I have been responsible for the training of our young hunters, a responsibility that I intend to continue on this new world.  I've had my eye upon you for a while now and it would be my honor to help train you in the ways of the {class}.\n\nShall we begin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9289] = { id = 9289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warrior Training", sourceObjective = "It is good that you seek my guidance.  For centuries I have taught young {race} warriors, so I may know a thing or two on how you should begin.  I see in you the makings of a great {class}, but only if you listen carefully to what I have to teach.\n\nAre you ready to learn, young {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9290] = { id = 9290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Training", sourceObjective = "I am pleased that you have come seeking my knowledge. We have much to do if your magical skills are to be honed.\n\nFor over a hundred years I have taught the arcane, frost and fire magics, and I can feel them just as strongly on this world.  Would you like me to impart some of what I know to you?", sourceObjectiveStatus = "unverified-source-field" }
quests[9291] = { id = 9291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priest Training", sourceObjective = "It gives me great hope for our future that you come seeking my wisdom.  While I have my hands full here with our injured, I am not so busy that I cannot spare a moment to aid you in your first steps as a {class}.  To walk in the Light is the highest of callings, and one that I am certain you are more than ready to undertake!\n\nSpeak with me again when you feel that you are ready to begin your training.", sourceObjectiveStatus = "unverified-source-field" }
quests[9292] = { id = 9292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracked Necrotic Crystal", description = "On the corpse of the fallen abomination, you discover a cracked crystal, slowly pulsing with necrotic energy.", sourceObjective = "Bring the Cracked Necrotic Crystal to Lieutenant Orrin outside the gates of Stormwind.", progress = "Is there something you need?", completion = "Hm, you took this from the corpse of one of the invading abominations?\n\nWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they wanted to create one inside Stormwind. It is good that they were unsuccessful.", sourceObjectiveStatus = "unverified-source-field" }
quests[9293] = { id = 9293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Must Be Done...", description = "The nearby lake has been contaminated by one of the ship's power crystals.  Many of the plants and animals of Ammen Vale have been mutated because of this.\n\nI have a theory on how to heal the lake, but I must have samples from the mutated lashers for analysis.  They can be found to the west in the Ammen Fields.\n\nWill you help me, {class}?", sourceObjective = "Gather 10 Lasher Samples and return them to Botanist Taerix at the Crash Site in Ammen Vale.", progress = "I'll need all of the samples in good condition if we're to have a chance of cleansing the lake.\n\nWe don't have much time, {class}!", completion = "These will do. Thank you, {class}!\n\nWhile you were out, I managed to gather some equipment together to make an analysis of the samples.  This should only take a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[9294] = { id = 9294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing the Lake", description = "Thank goodness, I think it'll work!  I have an agent for you to spread at Silverline Lake to the south.  It will neutralize the effects of the irradiated ship's power crystal that fell there.\n\nSwim out and scatter the neutralizing agent near it.  Don't worry, you won't be exposed long enough to become irradiated.", sourceObjective = "Disperse the Neutralizing Agent at the Irradiated Power Crystal, then return to Botanist Taerix at the Crash Site in Ammen Vale.", progress = "The sooner you disperse the agent at the lake, the fewer native creatures that will be mutated by drinking the water, including ourselves!\n\nI'm sorry that we can't do anything to help the poor creatures that have already been infected.  If only my lab equipment were intact.", completion = "From what you describe, the neutralizing agent worked! I just wish that I knew how long it will last; we really need to remove that power crystal from the lake entirely.\n\nThank you, {name}! I will tell Tedon to try the neutralizing agent on one of the captured beasts at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[9295] = { id = 9295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letter from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", sourceObjective = "Take the Torn Letter to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", sourceObjectiveStatus = "unverified-source-field" }
quests[9296] = { id = 9296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", sourceObjective = "Deliver the Dim Necrotic Stone to SOMEONE.", sourceObjectiveStatus = "unverified-source-field" }
quests[9297] = { id = 9297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", sourceObjective = "Deliver the Dim Necrotic Stone to SOMEONE.", sourceObjectiveStatus = "unverified-source-field" }
