quests[9301] = { id = 9301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envelope from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", sourceObjective = "Take the Bloodstained Envelope to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", sourceObjectiveStatus = "unverified-source-field" }
quests[9302] = { id = 9302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", sourceObjective = "Take the Crumpled Missive to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", sourceObjectiveStatus = "unverified-source-field" }
quests[9303] = { id = 9303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inoculation", description = "Zhanaa needs our help to salvage parts from the Exodar.  Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage.\n\nJust get close to the unaffected ones and use the crystal on them.  Unfortunately, you'll have to kill the others.  You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.", sourceObjective = "Use the Inoculating Crystal on 6 Nestlewood Owlkin. Then return to Vindicator Aldar at the Crash Site in Ammen Vale.", progress = "The more we can do to clear up Nestlewood, the faster Zhanaa can get back to work.", completion = "With many of the owlkin now inoculated, we can focus on getting out of here and not have to worry about wiping out the owlkin population in the area.\n\nHere, choose from these.  You've done good work, and you deserve to be rewarded!", sourceObjectiveStatus = "unverified-source-field" }
quests[9304] = { id = 9304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Document from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", sourceObjective = "Take the Smudged Document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", sourceObjectiveStatus = "unverified-source-field" }
quests[9305] = { id = 9305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spare Parts", description = "We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale.\n\nThere were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. \n\n{name}, you must go south to Nestlewood Thicket and Hills to find the spare parts.", sourceObjective = "Collect 4 Emitter Spare Parts and then return to Technician Zhanaa at the Crash Site in Ammen Vale.", progress = "When we have those spare parts, I know that we'll get this emitter repaired. With any luck there will be someone else out there left to talk to.", completion = "Let me take a look at those.\n\nYes, I think that these will do nicely; good job, {name}. The emitter is rather complex so it may take some time to finish the repairs. I'll let you know when it's ready.\n\nIn the meantime, you might see if Vindicator Aldar has anything he could use you for.", sourceObjectiveStatus = "unverified-source-field" }
quests[9309] = { id = 9309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Scout", description = "We now have several separate confirmations of unusual activity up on the Shadow Ridge.\n\nThis is disturbing; we thought that the scouting missions already undertaken had been thorough. One of my scouts hasn't reported back yet.\n\n{class}, I need you to head southwest to the other side of Silverline Lake and find Tolaan, and see what has delayed him.", sourceObjective = "Find and speak with Tolaan at Shadow Ridge in Ammen Vale.", completion = "Help... blood elves!  They... ambushed... me.  Don't have... long.", sourceObjectiveStatus = "unverified-source-field" }
quests[9310] = { id = 9310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faint Necrotic Crystal", description = "On the corpse of the fallen wight, you find a crystal that is faintly radiating necrotic energy.", sourceObjective = "Bring the Faint Necrotic Crystal to Lieutenant Rukag in the courtyard of the Undercity.", progress = "Can I help you with something?", completion = "You say this was taken from a wight attacking the city?\n\nWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they were trying to create one in the Undercity. We will have to be vigilant in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[9311] = { id = 9311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Elf Spy", description = "I have a plan. We must kill their leader. Without their master, perhaps they will retreat to regroup. We just need to buy time until the repairs are completed.\n\nThen Vindicator Aldar must know of this. Kill the surveyor, then return and tell him what we've found.", sourceObjective = "Slay Surveyor Candress and then inform Vindicator Aldar at the Crash Site in Ammen Vale.", progress = "Then it is true... a scouting party of blood elves here in Ammen Vale!  How did they follow us?\n\nI'll get someone out there immediately to bring Tolaan back.", completion = "I thank you for dealing with the blood elf surveyor.  Surely she was their leader.  Rest assured, we will deal with whatever remnant of them is still nearby.\n\nPlease, take one of these weapons as a sign of my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[9312] = { id = 9312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emitter", description = "{name}, while you were out investigating the Shadow Ridge, Zhanaa here has been going on about the holographic emitter.  You might want to speak with her.", sourceObjective = "Speak with Technician Zhanaa at the Crash Site in Ammen Vale.", completion = "I got it, I got it!  I think I managed to fix the emitter!  Here, I'll just activate this last crystal and that should do it.\n\nTake a look at the emitter, {name}.  It looks like it's beginning to work... someone is appearing!", sourceObjectiveStatus = "unverified-source-field" }
quests[9313] = { id = 9313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Travel to Azure Watch", description = "By all that is good, {name}, you must go at once to this Azure Watch and speak with Dyvuun!\n\nThere is a path that leads west off of this tiny isle.  Follow it and cross the Crystalbrook River to arrive on the larger part of the isle.  Continue to follow the path and you should find Azure Watch.\n\nSee if you can convince them to send us some aid and supplies.  The rest of us will follow when we can.\n\nThank you, we wouldn't have made it without you!", sourceObjective = "Speak with Technician Dyvuun at Azure Watch on Azuremyst Isle.", completion = "Ah, good to see you again!  I'm glad that we were both able to get our emitters fixed or we might never have found one another.  And don't worry, we'll see to it that Ammen Vale gets help and supplies.\n\nSpeaking of assistance, now that you're here, go around and introduce yourself to the others.  I know that there's plenty to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[9314] = { id = 9314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word from Azure Watch", description = "{class}! A couple mutated beasts jumped me and my leg is injured.\n\nI was sent on a scouting mission from Azure Watch after we received word from Zhanaa. Please, could you go speak with Caregiver Chellan in my stead? She needs to know how many people to expect in Azure Watch. Just cross the Crystalbrook River here and continue following the road until you get to Azure Watch.\n\nBe sure to ask her for a place for yourself to stay in.", sourceObjective = "Speak with Caregiver Chellan at Azure Watch on Azuremyst Isle.", completion = "Oh, you must be one of the survivors we've been hearing about!\n\nI'm glad that you came. Don't worry, we will send someone to see to Aeun's injured leg.\n\nI'm most interested in hearing all about your harrowing story of survival. You're a brave one to have made it all the way here.", sourceObjectiveStatus = "unverified-source-field" }
quests[9315] = { id = 9315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anok'suten", description = "Come closer, I am ... dying.\n\nI was sent here ... to slay these nerubians, but Vandril didn't ... know that they have a leader.\n\n<The dying blood elf coughs up a good amount of blood.>\n\nYou must find and ... slay Anok'suten.  Get help.  She wanders around ... Suncrown Village.", sourceObjective = "Slay Anok'suten and return to Arcanist Vandril at Tranquillien in the Ghostlands.", completion = "I apologize for the shoddy intelligence, {class}.  Had I known of this Anok'suten ahead of time, I surely would have told you.\n\nWe're spread too thin and things are slipping through the cracks!", sourceObjectiveStatus = "unverified-source-field" }
quests[9317] = { id = 9317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Sharpening Stones", progress = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", completion = "Thank you, {name}. Here are your consecrated sharpening stones. Use them prudently." }
quests[9318] = { id = 9318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Wizard Oil", progress = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", completion = "I hope that you will find these items useful in future battles." }
quests[9319] = { id = 9319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in Dark Places", description = "We are not the only ones who celebrate this holiday, {name}. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit.\n\nIf you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.", sourceObjective = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then return to the Festival Flamekeeper.", completion = "Your essence sings with the energy of the flames you found, {name}. The fire you encountered is potent, and with the right knowledge, its power can be harnessed...\n\n\n\nAh! Here we are. May this light your path, no matter where you tread.", sourceObjectiveStatus = "unverified-source-field" }
quests[9320] = { id = 9320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Mana Potion", progress = "In addition to our other supplies, we also have a number of major mana potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
quests[9321] = { id = 9321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Healing Potion", progress = "In addition to our other supplies, we also have a number of major healing potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
quests[9322] = { id = 9322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Fires in Kalimdor", description = "The Midsummer Fire Festival is celebrated everywhere in Azeroth, and the diverse land of Kalimdor is no exception. You look fit to travel -- perhaps a journey is in order.\n\nMidsummer cannot be truly appreciated unless you've seen the blistering blue fires abroad. The celebrants have lit fires in chilly western Winterspring, northeastern Azshara, near Valor's Rest in the wastes of Silithus, and by the entrance to lush Un'Goro. Return once your journey is complete.", sourceObjective = "Visit the Midsummer camps located in Azshara, Silithus, Un'Goro Crater, and Winterspring, then return to the Festival Flamekeeper.", completion = "Your spirit glows with the warmth of the Kalimdor fires, friend. Is the heat not invigorating?\n\n Once the power fades from you, perhaps these will help rekindle the feeling.", sourceObjectiveStatus = "unverified-source-field" }
quests[9323] = { id = 9323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Fires in the Eastern Kingdoms", description = "Our celebration of the flame is spread throughout the land, {class}. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue. Seek them out.\n\nYou'll find one just north of Blackrock Spire. The others are located deep within the Eastern Plaguelands near a decrepit town, along the road to the cliffs within the mountainous Hinterlands, and on the way to the Dark Portal within the Blasted Lands.\n\n Return once your journey is done.", sourceObjective = "Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper.", completion = "Ah, here you are. A little wearier, a bit dustier, but enlightened! The heat touches us all during this season and unites us; your very being glows with the power of the fires you touched.\n\nAh, but these days enlightenment is taken as a rather poor reward for being sent on a task, I suppose. Take these, then, and enjoy the celebration.", sourceObjectiveStatus = "unverified-source-field" }
quests[9324] = { id = 9324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Orgrimmar's Flame", description = "This flame, stolen from the heart of Orgrimmar itself, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", sourceObjective = "Return the Flame of Orgrimmar to the Festival Loremaster.", progress = "You're practically glowing, {race}. What do you have there?", completion = "What's this? Unless I'm mistaken, this flame has been taken from the heart of Orgrimmar itself! The fierce hearts of the orcs and trolls are reflected in its searing heat. What a fine addition to our collection--how brave you are, stealing into the enemy's lair to retrieve the sacred flame!\n\nI wonder what power lurks in the other cities...", sourceObjectiveStatus = "unverified-source-field" }
quests[9325] = { id = 9325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Thunder Bluff's Flame", description = "This flame, stolen from the shaman of Thunder Bluff, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", sourceObjective = "Return the Flame of Thunder Bluff to the Festival Loremaster.", progress = "You're practically glowing, {race}. What do you have there?", completion = "Unless I miss my guess, this fire has been taken from the cliffs of Thunder Bluff! How it sings with the power of the spirits! You are quite the thief, {name}. Take this as just payment for your skill. Now, if only we had the flames of all four cities...", sourceObjectiveStatus = "unverified-source-field" }
quests[9326] = { id = 9326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Undercity's Flame", description = "This flame, stolen from the ruins above the Undercity, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", sourceObjective = "Return the Flame of the Undercity to the Festival Loremaster.", progress = "You're practically glowing, {race}. What do you have there?", completion = "Hm... what a strange fire! It is subdued, nearly smoldering, but the heat is intense. And you received this from the Undercity, you say? Fascinating. With the flames of all four cities, who knows what we could accomplish?", sourceObjectiveStatus = "unverified-source-field" }
quests[9327] = { id = 9327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken", description = "I know it seems strange, but these Forsaken are here to help. You should speak with their leader, High Executor Mavren. He's in the tower on the west side of town.\n\nAnd, {class}, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", sourceObjective = "Speak with High Executor Mavren at Tranquillien in the Ghostlands.", completion = "I know that we Forsaken appear monstrous to your eyes, but I assure you we mean your people no harm. We are here because of a common enemy: Dar'Khan the traitor! He has returned and now commands the Scourge that are invading this land from his steadfast, Deatholme, to the south.\n\nOur leader, Lady Sylvanas Windrunner, originally hails from these lands, and in fact used to be an elf. She has a history with Dar'Khan and wants him dead as much as your people do.\n\nWe will defeat him together, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9328] = { id = 9328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero of the Sin'dorei", description = "This is the beginning of a new chapter in the history of our race, {name}.  Our lands will be reclaimed and we shall cement our bond with Sylvanas and her allies.\n\nTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City.  He'll be eager to hear the news.", sourceObjective = "Take Dar'Khan's Head to Lor'themar Theron in Silvermoon City.", progress = "You seek audience with me, {class}?  I do not recall hearing of an appointment.", completion = "Now that's one face I was not expecting to see so soon.\n\nThis is quite the good news, {name}, in more ways than you can imagine.", sourceObjectiveStatus = "unverified-source-field" }
quests[9329] = { id = 9329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken", description = "I know it seems strange, but the Forsaken are here to help. You should speak with their leader, High Executor Mavren.  He's in the tower on the west side of town.\n\nAnd, {class}, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", sourceObjective = "Speak with High Executor Mavren at Tranquillien in the Ghostlands.", completion = "We Forsaken are here because of a common enemy with the blood elves: Dar'Khan!  He has returned and now commands the Scourge that are invading this land from his steadfast, Deatholme, to the south.\n\nLady Sylvanas Windrunner, who originally hails from these lands, and used to be an elf, has a history with Dar'Khan and wants him dead!\n\nWe will defeat him, {class}, and you will help us do it!", sourceObjectiveStatus = "unverified-source-field" }
quests[9330] = { id = 9330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Stormwind's Flame", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", sourceObjective = "Return the Flame of Stormwind to the Festival Talespinner.", progress = "You're practically glowing, {race}. What do you have there?", completion = "And this brightly-burning fire... you say it came from Stormwind? Remarkable! That must have been quite an adventure! I'll pay you for this, of course. If you find anything else like this, be sure to speak with me again.", sourceObjectiveStatus = "unverified-source-field" }
quests[9331] = { id = 9331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Ironforge's Flame", description = "This flame, stolen from the heart of Ironforge itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", sourceObjective = "Return the Flame of Ironforge to the Festival Talespinner.", progress = "You're practically glowing, {race}. What do you have there?", completion = "This hearty flame must be from the halls of Ironforge; it's as stalwart as the dwarves themselves. A fine catch, {name}. If I had the fires of the other cities... ah, but never mind. Here is your payment.", sourceObjectiveStatus = "unverified-source-field" }
quests[9332] = { id = 9332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Darnassus's Flame", description = "This flame, stolen from the shores of Teldrassil, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", sourceObjective = "Return the Flame of Darnassus to the Festival Talespinner.", progress = "You're practically glowing, {race}. What do you have there?", completion = "This fire aches of ancient sorrow, {name}. You pulled this from the roots of Teldrassil, you say? Fascinating! Here is a reward for your skill. Return to me should you find anything else like this; I may have a use for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[9333] = { id = 9333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Dawn Gloves", progress = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", completion = "You've done well, {name}. Take your pick of hand protection in thanks for your efforts." }
quests[9334] = { id = 9334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Wizard Oil", progress = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", completion = "I hope that you will find these items useful in future battles." }
quests[9335] = { id = 9335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Sharpening Stones", progress = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", completion = "Thank you, {name}. Here are your consecrated sharpening stones. Use them prudently." }
quests[9336] = { id = 9336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Healing Potion", progress = "In addition to our other supplies, we also have a number of major healing potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
quests[9337] = { id = 9337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Mana Potion", progress = "In addition to our other supplies, we also have a number of major mana potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
quests[9338] = { id = 9338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to Cenarion Circle", progress = "Even if you have no need for the material rewards we offer, these badges still mark our mutual trust and friendship.\n\nBring them to me.  I'll make due note of your service should your performance go above and beyond the call of duty.", completion = "You honor us, {name}.  With your continued efforts we will overcome all obstacles." }
quests[9339] = { id = 9339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", sourceObjective = "Return the Flame of Stormwind to (NAME).", completion = "You've proven yourself today, {name}.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way.", sourceObjectiveStatus = "unverified-source-field" }
quests[9340] = { id = 9340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Fissure", description = "We're dangerously close to becoming fenced in by Alliance forces.  With the influx of sin'dorei pilgrims from Azeroth, we must establish a route that's safe from our enemies' prying eyes.\n\nI've given it some thought and have arrived at a solution.  We're to establish a secret path through the Great Fissure.\n\nYes, even though the area is crawling with brutal rock flayers, they are merely beasts and can be taught to fear us.  I want you to go and kill a good number of them.  They shall learn fear.", sourceObjective = "Ranger Captain Venn'ren at Falcon Watch wants you to slay 8 Stonescythe Whelps and 3 Stonescythe Alphas at the Great Fissure, east of Falcon Watch.", progress = "You've returned.  Is the task done?", completion = "Good job, {name}.  That should teach the rock flayers to stay far away from us.", sourceObjectiveStatus = "unverified-source-field" }
quests[9341] = { id = 9341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of the Argent Dawn", progress = "You have aided our cause greatly, {name}. If you wish, I can make available the tabard of the Argent Dawn. We are proud to have you among our allies.", completion = "Take this tabard and wear it proudly. Perhaps your deeds might inspire others to take up arms in support of our fight against the Scourge." }
quests[9342] = { id = 9342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marauding Crust Bursters", description = "As if the gan'arg that overran the mines aren't bad enough, now we've got gigantic worms encroaching on us from the other direction!\n\nWith Thrallmar's garrison pinned down defending against the Legion and tending to their wounded, it leaves me and the miners to deal with the problems.\n\n<The foreman gestures at the sleeping peons.>\n\nAnd you can see how useful they are...\n\nI'd gladly pay you their wages to clear out some of those worms.You will be able to choose one of these rewards:", sourceObjective = "Foreman Razelcraz at the mines near Thrallmar wants you to kill 15 Marauding Crust Bursters. The worms have a tendency to attack suddenly from their tunnels below ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[9343] = { id = 9343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of the Argent Dawn", progress = "You have aided our cause greatly, {name}. If you wish, I can make available the tabard of the Argent Dawn. We are proud to have you among our allies.", completion = "Take this tabard and wear it proudly. Perhaps your deeds might inspire others to take up arms in support of our fight against the Scourge." }
quests[9344] = { id = 9344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hasty Departure", description = "Greetings, {name}. Outland is a perilous place, as many of our expedition quickly learned. I'm afraid young Grelag may have learned that lesson firsthand.\n\nGrelag is a promising student, but he lacks patience! He eagerly studies the history of his people, but he sometimes forgets the threats of the present day.\n\nHe departed for the Spinebreaker Post, ignorant of the Legion and fel orc presences. I fear something may have happened to him.", sourceObjective = "Far Seer Regulkut wants you to track down her student Grelag.", sourceObjectiveStatus = "unverified-source-field" }
quests[9345] = { id = 9345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing the Salve", description = "Just as Zeth'Gor came into view, a Legion patrol caught sight of me. I ran, hoping to duck into one of the towers in the distance, but one of their felhounds caught up with me and nearly hamstrung me!\n\nI managed to escape, but my leg is in terrible shape. Stone Guard Ambelan found me and brought me here.\nNow, I have to find a way to tend to my leg. Spineleaf grows in and around the Valley of Bones to the north . A salve made from it will dull the pain enough for me to travel.", sourceObjective = "Gather 12 Hellfire Spineleaf plants for a salve and return to Grelag at Spinebreaker Post.", progress = "Have you brought the plants?", completion = "These should do the job. I'm going to prepare the salve and finish my splint before making my way back to Thrallmar. Why do I have the feeling that I know what Far Seer Regulkut will say when she sees me?\n\n<Grelag sighs half-heartedly.>\n\nThank you for your help, {name}. I have some of the spineleaf left over. You're welcome to take it with you. Who can tell when it will prove useful?", sourceObjectiveStatus = "unverified-source-field" }
quests[9346] = { id = 9346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Helboars Fly", description = "Have you ever seen a helboar fly? They don't even need wings!\n\n<Watch Commander Krunk laughs.>\n\nThe fight against the Legion camps to the north has depleted our supplies, including catapult ammunition. This is the perfect opportunity to try something new.\n\nInstead of using boulders, I want to try igniting the corpses of the starving helboars I've seen around the eastern ruins and use them to bombard the Legion's camps.\n\nAre you going to volunteer, or do I have to order you?", sourceObjective = "Watch Commander Krunk in Thrallmar wants you to bring him 10 Plump Helboar Carcasses from Starving Helboars.", sourceObjectiveStatus = "unverified-source-field" }
quests[9347] = { id = 9347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidwalkers Gone Wild", description = "Examining the essence reveals violent swirls of energy sealed within a vessel made of unidentifiable material. As you consider it, you can feel it beginning to tug at your mind, inviting you to come closer and to look deeper.\n\nFeeling your will begin to slip away, you break your gaze immediately. Its presence remains at the edge of your consciousness as you determine what to do with it.", sourceObjective = "Bring the Pulsating Voidwalker Essence to Mahuram Stouthoof in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9348] = { id = 9348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravager Roundup", description = "Outland is rife with fascinating creatures. Fascinating -- and extremely dangerous.\n\nThe area is rich with predators, which seems strange for such a barren land, but a closer look reveals something of a hierarchy.\n\nThe rock flayers seem to have domesticated another predator, the ravager, and breed them as hunting companions and guard animals. I need to know more about how they're training these ravagers. We must shut down and examine their breeding site to the southwest, near the Terokkar Forest.You will be able to choose one of these rewards:", sourceObjective = "Slay 10 Captive Ravager Hatchlings and retrieve 12 Ravager Eggs for Mahuram Stouthoof in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9349] = { id = 9349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravager Egg Roundup", description = "I'm starving!\n\nThere's irony in that, wouldn't you say?  A starving cook?\n\n<Legassi laughs half-heartedly and taps a folded piece of parchment he has in his pocket.>\n\nAccording to this tourist map we were following - before we were so rudely shot down - there's an area to the southwest, near Terokkar Forest.  It's called the Razorthorn Trail, and supposedly it's brimming with delicious ravager eggs!\n\nI could cook up quite a feast if only someone were brave enough to go down there and get me some!", sourceObjective = "Retrieve 12 Ravager Eggs for Legassi at the Zeppelin Crash in Hellfire Peninsula.", progress = "You have those eggs yet?\n\n<Legassi's stomach grumbles in anticipation.>", completion = "In order to have great cuisine, you need to have great ingredients.  And these eggs look great!\n\nI've just finished cleaning off my frying pan, so you're more than welcome to join me for a meal!", sourceObjectiveStatus = "unverified-source-field" }
quests[9350] = { id = 9350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Peon's Work is Never Done", description = "The Legion's constant assaults take a heavy toll on our defenses. If the palisade falls, so will Thrallmar. I've assigned peons to reinforce and repair the walls, but we're running out of materials.\n\nGrelag, one of the Far Seer's students, is well versed in the old ways and suggested returning to an ancient practice. Long ago, the clefthoof hunt supplied us with meat, hides, and bones. Taking up the hunt again, with the clefthoof to the southeast, would provide what's needed and honor the ancestors.You will be able to choose one of these rewards:", sourceObjective = "Gather 8 Clefthoof Hides and 8 sets of Clefthoof Bones from the Raging Clefthoof. Return to Watch Commander Krunk in Thrallmar once you have all the materials.", sourceObjectiveStatus = "unverified-source-field" }
quests[9351] = { id = 9351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidwalkers Gone Wild", description = "Even if I can get the zeppelin's frame repaired, I'll have to find something else to power the engine. I'm all out of fuel and there's no place to fill up around here!\n\nTo the south of us is an area of broken land called the Warp Fields. It's full of rogue and uncontrolled voidwalkers, but I like to think of them as walking batteries.\n\nIf you can bring me enough of their essence, I can convert the zeppelin's engine to run on it. Five gold says I'll even get better mileage out of it, too!", sourceObjective = "Bring 10 Condensed Voidwalker Essences to \"Screaming\" Screed Luckheed at the Zeppelin Crash.", progress = "Were you able to get the essence?", completion = "This is perfect! In fact, I think it's going to work so well, I might just have to redesign the engine to take advantage of all this extra power. If, I mean, when we get out of here, I'll have to show my design to everyone back at Area 52!", sourceObjectiveStatus = "unverified-source-field" }
quests[9352] = { id = 9352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassian Intrusions", description = "Besides the constant threat that the Wretched represent, I also have to deal with all kind of fictitious reports of night elf sightings.\n\nThough most reports are unfounded, one recent incident demands further investigation.  The West Sanctum, one of our primary energy sources, has suffered a terrible malfunction and rumors of Darnassian sabotage are rampant.\n\nTravel there and deal with anyone that looks suspicious.  Report back to Ley-Keeper Velania, who watches over the sanctum.", sourceObjective = "Travel to the West Sanctum, southwest of Falconwing Square and defeat any intruders present there. Report your findings to Ley-Keeper Velania.", completion = "Night elves?  Here?  Those rats!\n\nDo you suppose they had anything to do with the malfunction in my sanctum?  If you have any information, you'd better take it to Captain Sunbrand at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[9353] = { id = 9353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeem iCoke Gift Box Voucher" }
quests[9354] = { id = 9354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for New Materials", description = "<The dwarf looks up from his work expectantly.>\n\nIf you're looking to commission a piece, get in line, {class}. I've got my hands full maintaining the Sons' equipment and preparing us for the day when we'll take the battle to the enemy again.\n\nOur metal stocks are getting very low since crust borers invaded the mines. I've been experimenting with natural materials from the raging clefthoof that graze in the areas northeast of the Hold, and while they're no substitute for iron, I'm learning to make do.You will be able to choose one of these rewards:", sourceObjective = "Gather 8 Clefthoof Hides and 8 Clefthoof Sinews from the Raging Clefthoof. When you have the materials, bring them to Humphry in Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9355] = { id = 9355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Job for an Intelligent Man", description = "Well met, {class}. Now that reinforcements are finally arriving, we can recapture some semblance of a normal life.\n\nOne of our first goals is to restore the flow of men and goods along the road to the southwest, but it must be reclaimed from the crust bursters that've overrun the area.\n\nIf you're willing to help us deal with this menace, you would have the gratitude of the Sons. Watch carefully for the disturbed ground they leave in their wake.", sourceObjective = "Kill 15 Marauding Crust Bursters and return to Foreman Biggums at Honor Hold.", progress = "Were you able to clear the road?", completion = "Well done, {name}. We shouldn't be too quick to congratulate ourselves, though. I'm certain we haven't seen the last of those worms. If they show their hideous heads around these parts again, the Sons'll be ready for them!", sourceObjectiveStatus = "unverified-source-field" }
quests[9356] = { id = 9356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smooth as Butter", description = "Screed likes to say his flying is as \"smooth as butter.\" I think \"butterfingered\" is more like it!\n\nTake a look at the wreckage over there. He calls it a \"rough\" landing.\n\nSure, we got shot at, but I'd be willing to cut him a little more slack if he didn't brag about his piloting skills so often!\n\nI think I'm going to make him a batch of wings to drive the point home. To the east, in the Valley of Bones, you'll find bonestripper buzzards. Their wings are plump, juicy, and perfect for my needs.", sourceObjective = "Bring 12 Plump Buzzard Wings to Legassi at the Zeppelin Crash.", progress = "I can't wait to see the look on his face when he digs in. Ever since the crash, he's been complaining that all I can think of is food. Well, someone's got to feed us while he tinkers with the zeppelin!", completion = "Ravager Eggs.  Bam!\n\nHellboar Bacon. Bam!\n\nBuzzard Wings. Bam!  Bam!\n\nWhat a great meal.  You've really got to try it.", sourceObjectiveStatus = "unverified-source-field" }
quests[9357] = { id = 9357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Aeldon Sunbrand", description = "If you're looking for work, you'll find Captain Sunbrand inside the Inner Elf Gate, through the doors behind me.\n\nNow leave me be, I must question this scoundrel.", sourceObjective = "Report to Aeldon Sunbrand at the Inner Elf Gate in Eversong Woods.", sourceObjectiveStatus = "unverified-source-field" }
quests[9358] = { id = 9358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranger Sareyn", description = "Don't take the safety of this village for granted.  We're under siege by the Scourge on the east and the Wretched to the west.\n\nRanger Sareyn keeps our borders safe from the undead that pour in from the Dead Scar.  Follow the road eastwards out of town and see if you can lend her a hand.", sourceObjective = "Report to Ranger Sareyn outside Fairbreeze Village in Eversong Woods.", completion = "You're here to help us?  Why didn't you say so earlier?  We can always use a hand!", sourceObjectiveStatus = "unverified-source-field" }
quests[9359] = { id = 9359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farstrider Retreat", description = "Your help in subduing the Wretched has been invaluable.  The Farstriders would surely have use for someone like you in their fight against the Amani trolls.\n\nLook for the Farstrider Retreat to the northeast of here, speak to Lieutenant Dawnrunner and see what assistance she might need.", sourceObjective = "Report to Lieutenant Dawnrunner at the Farstrider Retreat in Eversong Woods.", completion = "You're here to help?  Excellent!\n\nThe battle against the Amani trolls has taken its toll on us and capable fighters such as yourself are always welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[9360] = { id = 9360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amani Invasion", description = "Though you don't understand the language in these battle plans, you clearly make out a map marking the positions of the Farstrider Retreat and Fairbreeze Village.\n\nYou'd best let Lieutenant Dawnrunner at the Farstrider Retreat know about this.", sourceObjective = "Deliver the Amani Invasion Plans to Lieutenant Dawnrunner at Farstrider Retreat.", progress = "What do you want to show me?", completion = "The trolls have been keeping us pinned here while planning an attack on Fairbreeze Village.  We were not expecting this at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[9361] = { id = 9361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helboar, the Other White Meat", description = "Those eggs are superb, but what do you say we kick it up another notch?\n\nA side of bacon would round out the meal perfectly and I know just where to get it.\n\nThis place is littered with helboars. Of course, there's no one here to inspect and tenderize the meat, but we're in luck!\n\n<Legassi rummages around in his pack and produces a flask.>\n\nThis wasn't made for use on pork, but cooking is as much about improvisation as anything else!", sourceObjective = "Legassi at the Zeppelin Crash wants you to gather 8 Purified Helboar Meat. To purify the meat, use the Purification Mixture on the Tainted Helboar Meat you gather from Helboars.", progress = "Were you successful in purifying the helboar meat?", completion = "Hmm...\n\nThis looks edible, if spiced properly. Just don't tell Screed where his breakfast came from, ok?", sourceObjectiveStatus = "unverified-source-field" }
quests[9362] = { id = 9362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord Krellian", description = "There isn't much time, {name}!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.\n\nThe pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor.  Burn him to ashes and take the prismatic shell he covets so dearly.", sourceObjective = "Retrieve the Prismatic Shell for Archmage Xylem. The Archmage resides in a tower atop the cliffs of Azshara.", progress = "There is not time to waste!  Have you the shell?", completion = "I must say, this shell has a strange aura.  It seems only fitting that part of your reward for retrieving it would be to test its magical capabilities...", sourceObjectiveStatus = "unverified-source-field" }
quests[9363] = { id = 9363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning Fairbreeze Village", description = "Go to Fairbreeze Village and notify Ranger Degolien of the Amani plans.  Even with Zul'Marosh dead, Fairbreeze must prepare for a troll attack.  Tell Degolien I will send him reinforcements as soon as possible.", sourceObjective = "Travel to Fairbreeze Village in Eversong Woods and speak to Ranger Degolien.", completion = "The information you've brought is of vital importance, {name}.  Now that we know of the trolls' plans we can prepare for an attack.\n\nWe won't be caught with our guard down.", sourceObjectiveStatus = "unverified-source-field" }
quests[9364] = { id = 9364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmented Magic", description = "My research has revealed a unique purpose for the prismatic shell.\n\nCarry the shell and cast your polymorph spell on the Spitelash in Azshara.  If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments.  Kill these clones as quickly as possible, and the shell will collect their essence.\n\nWhen the shell is full, return it to me.", sourceObjective = "Polymorph the Spitelash of Azshara and kill the clones that appear several seconds later. When you have slain 50 Polymorph Clones, return to Archmage Xylem in Azshara.", progress = "Have you collected the magic?", completion = "Splendid!  Splendid!\n\nNow we are able to reform this magic into a new spell.  Behold!", sourceObjectiveStatus = "unverified-source-field" }
quests[9365] = { id = 9365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", sourceObjective = "Return the Flame of Stormwind to (NAME).", completion = "You've proven yourself today, {name}.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way.", sourceObjectiveStatus = "unverified-source-field" }
quests[9366] = { id = 9366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Need of Felblood", description = "Northeast of here lie the Pools of Aggonar.  Once a sacred site to the draenei, their waters were corrupted after the blood from the demon Aggonar was spilled into them.\n\nThat blood, though old and diluted, still possesses tremendous power.  Terrorfiends now walk the area, empowered by the pure demonic energies of the original blood.  Slay them and retrieve as much felblood as you can.  I'll make it worth your while.", sourceObjective = "Ryathen the Somber at Falcon Watch in Hellfire Peninsula wants you to bring him 6 Felblood Samples from the Terrorfiends that inhabit the Pools of Aggonar.", progress = "The felblood... did you obtain it, {name}?", completion = "The energy contained in these samples is tremendous, {name}.  Now we just need to ensure that our access to this felblood continues uninterrupted.", sourceObjectiveStatus = "unverified-source-field" }
quests[9367] = { id = 9367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", sourceObjective = "Touch the bonfires within Stormwind, Ironforge, and Darnassus, then speak to a Festival Loremaster within the capital cities.", completion = "Excellent! It seems we've appointed dutiful Flamekeepers this year if the bonfires are as well-kept as you claim. Thank you for inspecting them for me; here, take this as a small token of my esteem.", sourceObjectiveStatus = "unverified-source-field" }
quests[9368] = { id = 9368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", sourceObjective = "Touch the bonfires within Orgrimmar, Thunder Bluff, and the Undercity, then speak to a Festival Talespinner within the capital cities.", progress = "Are the fires burning?", completion = "Excellent! It seems we've appointed dutiful Flamekeepers this year if the bonfires are as well-kept as you claim. Thank you for inspecting them for me; here, take this as a small token of my esteem.", sourceObjectiveStatus = "unverified-source-field" }
quests[9369] = { id = 9369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenishing the Healing Crystals", description = "We are the draenei.  Our ship crashed and, since we have many wounded, our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!\n\nUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.\n\nThe moths can be found in many places around the vale, but mostly in the northwest.", sourceObjective = "Acquire 8 Vials of Moth Blood from the nearby Vale Moths and bring them to Proenitus at the Crash Site in Ammen Vale.", progress = "Have you harvested the necessary moth blood for the healing crystals yet?  With survivors scattered all over the vale, time is of the essence!", completion = "Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the draenei way.  However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[9370] = { id = 9370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing Must Be Stopped", description = "Our scouts captured a draenei paladin at the Pools of Aggonar.  He was to take part in a cleansing ritual to purify the pools.  We must stop the draenei from succeeding or we will lose our supply of felblood!\n\nHe was carrying this signaling gem, looking to mark a spot where a priest - or \"anchorite\" as they call themselves - could perform their rituals in safety.  Place the gem near the Altar of Aggonar and be ready to ambush any approaching draenei.\n\nI suggest that you take a friend or two along.", sourceObjective = "Place the Signaling Gem near the Altar of Aggonar at the Pools of Aggonar and defeat any Draenei Anchorites that respond to your summons. Return to Ryathen the Somber at Falcon Watch with the Signaling Gem after completing this task.", progress = "You've returned, {name}.  Did you put an end to the draenei's folly?", completion = "That'll show those holy fanatics to mind their own business.", sourceObjectiveStatus = "unverified-source-field" }
quests[9371] = { id = 9371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanist Taerix", description = "{name}, Botanist Taerix is in need of your assistance. You'll find her with her apprentices to the west, outside the ship.", sourceObjective = "Speak with Botanist Taerix at the Crash Site in Ammen Vale.", completion = "Oh, thank goodness you've come.  We have much to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[9372] = { id = 9372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Contamination", description = "Welcome to the Cenarion Post, {class}. We don't often get company out here, but I'm grateful for the visit. My work with the creatures of this desolate land requires me to travel to many remote places.\n\nThe Cenarion Expedition has dispatched me to study some of the most dangerous wildlife in Outland, and I've made a startling discovery. While many creatures here have already undergone radical changes, they continue to mutate. I'm collecting blood samples to document the changes, and any help would be welcome.", sourceObjective = "Thiah Redmane, at the Cenarion Post in Hellfire Peninsula, has asked you to gather 6 Helboar Blood Samples from Hulking Helboars.", progress = "Were you able to collect the blood samples?", completion = "Well done, {name}. These blood samples will prove helpful in my research and in the Expedition's wider studies of Outland's creatures.\n\nIf I could isolate what causes these creatures to change continuously, perhaps I could concoct an antidote.", sourceObjectiveStatus = "unverified-source-field" }
quests[9373] = { id = 9373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Missive", description = "Upon examining the battered leather case, it becomes apparent that the container's damage must've been caused by the caustic fluid of the worm's digestive tract. The leather appears to have been intricately tooled at one time, but the details of its adornment can no longer be made out.\n\nThe only recognizable feature of the case is a worn logo of the Cenarion Circle. Knowing nothing about the contents of the case, you decide the best course of action would be to deliver it to a Circle member.", sourceObjective = "Return the Eroded Leather Case to Thiah Redmane, camped near the Ruins of Sha'naar in western Hellfire Peninsula.", progress = "Good day, {class}. What brings you to my encampment?", completion = "Thank you for bringing this to me, {class}. I was wondering why I hadn't heard from the Expedition in so long. I wonder how long ago this message was dispatched and what befell its carrier.\n\nHere's a bit of coin for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[9374] = { id = 9374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelion's Journal", description = "My husband, Arelion, had been fascinated with the Pools of Aggonar ever since we arrived in Outland.  He spent much of his time studying slimes, of all things!\n\nHe went missing in there a few days ago.  They say he's dead and there's nothing I can do about it.\n\nOne thing I can do is try to ensure that his research doesn't die with him.  Go northeast to the pools and look for his journal.  He always carried it inside a brown knapsack.", sourceObjective = "Magistrix Carinda at Falcon Watch in Hellfire Peninsula wants you to go to the Pools of Aggonar and retrieve Arelion's Journal.", progress = "Any luck, {name}?  You'll find the Pools of Aggonar north of Hellfire Citadel.", completion = "My husband's journal... it's not about research at all!\n\nHow could I've been such a fool?  \"Magical properties of fel-infused slime forms,\" he really had me going there.", sourceObjectiveStatus = "unverified-source-field" }
quests[9375] = { id = 9375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Falcon Watch", description = "<The battered blood elf's face displays relief at your presence.>\n\nPlease, {class}, get me out of this cage! I foolishly set out from Thrallmar ahead of the main group, despite Martik Tor'seldori's warnings.\n\nI was set upon by horrible creatures that could only be the ravagers he talked about. I managed to drive them off, but that was only the beginning of my troubles.\n\nAs I bound my wounds, those bird men found me, dragged me back to this cave, and locked me in this cage! I must get to Falcon Watch!", sourceObjective = "Protect the Wounded Blood Elf Pilgrim on her way to Falcon Watch, then speak with Taleris Dawngazer.", progress = "What do you need, {class}?", completion = "<Taleris shouts to several of the blood elves at the outpost.>\n\nGet her inside and see to her wounds!\n\n<Taleris turns back to you.>\n\nShe's fortunate that you found her when you did, {class}. I don't think she'd have lasted much longer out there.\n\nCan you make out what she was saying?", sourceObjectiveStatus = "unverified-source-field" }
quests[9376] = { id = 9376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pilgrim's Plight", description = "That wounded pilgrim seems to be shouting something about a pack.\n\nWhen you encountered her, did you see a pack nearby? Hmm...\n\nShe must've left it when fleeing from her attackers. The quillfang ravagers, in their ravine to the south, are known to attack solitary travelers.\n\nIf she doesn't calm down, I won't be able to tend her wounds. Her stubbornness may just cost her her life.\n\nGo to Dustquill Ravine and see if you can find her campsite. I'm willing to bet she left it there.", sourceObjective = "The Wounded Blood Elf Pilgrim was attacked by Quillfang Ravagers while camped in Dustquill Ravine. Find her camp and search it for the missing pack.", progress = "Things aren't going well. At this rate, she'll never make it back onto the road. Were you able to find that pack?", completion = "Thank you for returning this, {name}. I'm not sure what significance it holds for the wounded pilgrim, but she refuses to let anyone get near her until it's in her hands again.", sourceObjectiveStatus = "unverified-source-field" }
quests[9377] = { id = 9377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thirsting For Power", description = "Falcon Watch serves as a stop for pilgrims on their long journey into Outland. Although we are an early stop on the way, many of the pilgrims reach us exhausted and wracked by their addictions.\n\nIn a world such as this, many find it necessary to relearn mastery of their magical addiction. Food and drink help, {class}, but magical energy is their greatest need. The remains of Outland's voidwalkers provide a potent source of energy, but they grow rare and can only be found in the Warp Fields to the southwest.", sourceObjective = "Retrieve a Potent Voidwalker Essence from the Vengeful Voidwalkers and return to Taleris Dawngazer at Falcon Watch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9379] = { id = 9379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortifying the Felhunter", description = "Greetings, {class}. Say hello to Jir'see here, too. Don't worry, he won't bite unless I tell him to.\n\n<Angela makes a cooing sound at the felhunter.>\n\nHe's so tiny in comparison to the warp hounds that live in Outland. But we're going to fix that right up, yes we are, aren't we, Jir'see?\n\nI think I've figured out a way to do it. I'll need plenty of blood from the warp hounds and that's where you come in. While you're hunting them in the southeast, I'll get ready for the experi... err, treatment.", sourceObjective = "Gather 6 Warp Hound Blood and bring them to Angela \"The Claw\" Kestrel in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9380] = { id = 9380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hounded for More", description = "I swear, if I get one more letter from Ironforge...\n\nHave you ever tried to explain something to someone who just wouldn't listen, {class}? I sent the boys in Ironforge the warp hound they asked for, and they had the gall to write back saying they wanted a \"pack\" of the things! A pack!\n\nSo, I tried to tell 'em that warp hounds are solitary creatures, but they'd have none of it. I've given up on setting 'em straight. Grab 6 of the best ones from the area east of the hold, and brimg 'em back here?", sourceObjective = "Collect 6 Undamaged Warp Hound Corpses and bring them to Prospector Murantus in Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9381] = { id = 9381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trueflight Arrows", description = "With the influx of pilgrims and the encroachment of Alliance forces, things around Falcon Watch have gotten quite busy lately. In my spare time, I usually help prepare batches of arrows for the rangers, but I haven't had the chance to gather feathers for the fletching in a long time.\n\nI could offer you a bit of coin if you'd be willing to gather the tail feathers of the bonestripper vultures. In the past, I've found them circling the bones of large beasts to the north of Falcon Watch.", sourceObjective = "Gather 8 Bonestripper Tail Feathers from Bonestripper Vultures and bring them to Falconer Drenna Riverwind at Falcon Watch.", progress = "Were you able to get all the feathers?", completion = "These should do the job. I was concerned that the rangers might be short on arrows for a while, but that's one less thing I have to worry about. Thank you for your help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9382] = { id = 9382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Clefthoof", description = "Greetings, {class}.\n\nI'm certain your travels in Outland have shown you something of the corruption in this world. It is so pervasive that it has transformed the very creatures who dwell here - the ones that survived, that is.\n\nThe clefthoof to the south and west were once docile grazers, but the corruption has created an unquenchable rage in them. They only find release from their torment in death, though it grieves us to spill their blood. Will you help me end the suffering of the bristlehide clefthoof?You will be able to choose one of these rewards:", sourceObjective = "Kill 15 Bristlehide Clefthoof and return to Amaan the Wise at the Temple of Telhamat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9383] = { id = 9383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ambitious Plan", description = "The blood elves epitomize the irresponsible use of magic, {class}. They do not control magical energy. Rather, they are slaves to it and will suffer nothing to stand between them and their addiction. They consume the energies of Outland's voidwalkers to power their demonic magics.\n\nI've prepared a crystal charged with a spell that will allow us to neutralize a voidwalker and sever its link to this world when destroyed. I've mostly seen the voidwalkers in the Warp Fields to the southeast of Hellfire Citadel.", sourceObjective = "Use the Sanctified Crystal against a wounded Uncontrolled Voidwalker and return to Elsaana at the Temple of Telhamat.", progress = "Have you used the crystal's magic against an uncontrolled voidwalker?", completion = "You've done well, {name}. It seems the containment crystal is holding for now, but how long it will last remains a mystery. We'll keep an eye on it and prepare more of the crystals in the meantime.", sourceObjectiveStatus = "unverified-source-field" }
quests[9385] = { id = 9385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampaging Ravagers", description = "So Honor Hold sends us to deal with the arakkoa and we set up camp here thinking hey isn't this a great spot.  Little did we know how close we were to the quillfang ravagers.\n\nThey are relentless predators and have made any sort of work on our part impossible.  There's a bit of coin in it for you if you can deal with them for us.  Do you feel up to it?", sourceObjective = "Kill 10 Quillfang Ravagers and return to Gremni Longbeard in Hellfire Peninsula.", progress = "Have you made any progress against the ravagers?", completion = "Well done, {name}.  That should teach those beasts who's boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[9386] = { id = 9386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in Dark Places", description = "An eager one, aren't you? If you're willing to enter the depths once more, I'll gladly reward you.\n\nSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, {name}.", sourceObjective = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper.", sourceObjectiveStatus = "unverified-source-field" }
quests[9387] = { id = 9387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Source of the Corruption", description = "Uncorrupted draenei, like this unlucky fellow here, are virtuous champions of the Light.  What corruption caused their great race to devolve into the Broken and Lost Ones?\n\nI've heard a theory that exposure to fel energies is what caused the mutation.  I would like to put that theory to the test.\n\nNorthwest of here lie the Ruins of Sha'naar.  There you will find lowly Broken commanded by Illidari taskmasters.  Bring me demonic essences from the taskmasters so that I can test them on this draenei.", sourceObjective = "Travel to the Ruins of Sha'naar in Hellfire Peninsula and obtain 5 Demonic Essences from the Illidari Taskmasters. Return to Apothecary Azethen at Falcon Watch after you've completed the task.", progress = "Have you obtained the samples?", completion = "You've been most helpful, {name}.  Now let's see what we can learn from our blue friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[9388] = { id = 9388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Flames in Kalimdor", description = "There are many flames burning throughout the world today, {name}. The trickiest fires to tend are those that burn green; they do not stay lit long without supervision. Make certain the emerald fires still burn on Kalimdor for our Flamekeeper, eh?\n\nYou will find them near Ratchet in the Barrens, close to the Master's Glaive in Darkshore, in the forest of Ashenvale by the bridge near Silverwing Outpost, and near the road to Windshear Crag along the main road in Stonetalon Mountains.", sourceObjective = "Visit the bonfires within Ashenvale, the Barrens, Darkshore, and Stonetalon Mountains, then speak with the Festival Flamekeeper.", completion = "Ahhh, so they do still burn. I am glad; it would not do for those fires to burn out before their time. You have done well, {name}. Take this with my blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[9389] = { id = 9389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Flames in the Eastern Kingdoms", description = "The Midsummer Fire Festival traditionally lights up the land with a myriad of flames. Some argue that the green fires are the finest, as they are the hardest to maintain and have such a distinctive hue.\n\nMake sure they still burn in the Eastern Kingdoms for our Flamekeeper. They sit near Dun Modr in the Wetlands, close to Pyrewood Village within Silverpine Forest, on the cliffs overlooking the lighthouse in Westfall, and by the ruined tower in Hillsbrad Foothills.", sourceObjective = "Visit the bonfires within Hillsbrad Foothills, Silverpine Forest, Westfall, and the Wetlands, then speak with the Festival Flamekeeper.", progress = "Have you seen to your task?", completion = "So you've returned, and you've seen to the emerald flames of the continent. What do you think, mm? A rare and wonderful sight, to be certain. I am aware, however, that tangible rewards are better appreciated... so please, take this for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[9390] = { id = 9390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Sedai", description = "Hear my plight, {class}.  My brother, Sedai, left long ago to contact the orcs of Mag'har Post.  Ever the idealist, he thought the time was ripe to set our differences aside and negotiate a peace with them.\n\nHe's been missing for days and I fear for the worst.\n\nWould you set my mind to rest and look for him?  Sedai must be somewhere nearby to the east.", sourceObjective = "Anchorite Obadei wants you to look for his brother, Sedai, nearby to the east in Hellfire Peninsula.", completion = "You've found the body of a young draenei paladin.  He appears to have been slain by a blow to his back.", sourceObjectiveStatus = "unverified-source-field" }
quests[9391] = { id = 9391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marking the Path", description = "With the rock flayer population thinned, all that's left is to signal the safe path to our pilgrims.  Return to the Great Fissure with this torch and seek the three beacons that mark the path from the east.\n\nLight the three beacons and return to me.  Be warned that the beacons will attract any nearby rock flayers when you first light them.", sourceObjective = "Ranger Captain Venn'ren at Falcon Watch wants you to go to the Great Fissure in Hellfire Peninsula and light the Southern Beacon, Western Beacon and Central Beacon. Return to him with the Lit Torch after you've completed this task.", progress = "Have you done what I asked of you, {name}?", completion = "The Great Fissure, though still dangerous, will prove to be a useful path for our pilgrims.\n\nWith the Alliance watching all the roads in and out of Falcon Watch this is the manner of desperate act that is required of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[9392] = { id = 9392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rogue Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young rogues here on Sunstrider Isle, your trainer is Pathstalker Avokor.  Speak with Avokor and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nAvokor - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", sourceObjective = "Speak with Pathstalker Avokor - the Rogue class trainer - inside the Sunspire on Sunstrider Isle.", completion = "I've heard your name whispered from the shadows, {name}.  It's said that you're looking for someone experienced to show you the ropes - someone like me.  I can do that, but it'll cost you a small cut of your take every time I've got something to teach you.  So yes, I will train you in what it means to be a {class}.\n\nBut remember, if you get caught stealing something, this conversation never took place.  Now get out there and show me what you're made of!", sourceObjectiveStatus = "unverified-source-field" }
quests[9393] = { id = 9393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young hunters here on Sunstrider Isle, your trainer is Ranger Sallina.  Speak with Sallina and see what training she has available for you.  The things she will teach do have a cost, so bring some coin with you.\n\nSallina - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", sourceObjective = "Speak with Ranger Sallina - the Hunter class trainer - inside the Sunspire on Sunstrider Isle.", completion = "{name}, are your eyes keen as a hawk's, your motions as fluid as a monkey's, or your speed that of a cheetah?  Mine are, and yours can be too with the proper training.  The way of the {class} is one of mastery over the beasts of the world, an unparalleled precision in marksmanship, and the knowledge of how to survive in situations where others would perish.\n\nIf these are the things that you seek to learn, then I will train you - for a small fee, of course.  Shall we begin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9394] = { id = 9394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Wyllithen?", description = "The Duskwither groundskeeper has gone missing! Someone must have forgotten to tell him to leave when the magister and everyone else did.  I know that he's still somewhere around here on the grounds, but I dare not go looking for him myself with all of these magical creatures roaming about.\n\nWill you find him for me, {class}, and make sure that he's alright?", sourceObjective = "Find Groundskeeper Wyllithen on the Duskwither Grounds in Eversong Woods.", completion = "Who are you?  You're not one of the magister's apprentices, that's for certain!\n\nSent here to help me clean up this mess, no doubt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9395] = { id = 9395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltheril's Haven", description = "I swear that I'm going to fireball someone if I get one more request from Lord Saltheril concerning supplies for his party!  Do I look like a party planner?!  Between you and me, that fool and his sycophants are living in denial that we're under attack here!\n\nSome of us are actually busy with, oh, I don't know, defending what's left of Quel'Thalas!  {class}, would you please head over to Saltheril's Haven and see if you can shut him up?  It's just down the road to the west.", sourceObjective = "Speak with Lord Saltheril at Saltheril's Haven in Eversong Woods.", completion = "Ah, good of Magistrix Dawnstrider to finally respond to my simple requests.  I should take up the matter of her attitude with the regent lord in Silvermoon. She's quite rude!\n\nNothing for you to concern yourself with though. Now that you're here, maybe I'll finally be able to get those party supplies that I've been waiting for?", sourceObjectiveStatus = "unverified-source-field" }
quests[9396] = { id = 9396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic of the Arakkoa", description = "Outland holds many secrets, {name}.  It's only a matter of time before we uncover them all.\n\nThe half-bird, half-man species of the arakkoa possesses ancient arcane knowledge that would aid us greatly in our exploration of this world.  Travel to the Den of Haal'esh, south of here.  Obtain any magical scrolls that the Haal'eshi might be carrying on them and bring them to me.", sourceObjective = "Bring 4 Haal'eshi Scrolls to Arcanist Calesthris Dawnstar at Falcon Watch in Hellfire Peninsula.", progress = "Have you obtained the scrolls yet, {name}?", completion = "Good work, {name}.  Outland's secrets will not stay hidden from us for very long.\n\nIt's our destiny to become the masters of this world.", sourceObjectiveStatus = "unverified-source-field" }
quests[9397] = { id = 9397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Birds of a Feather", description = "The Haal'eshi arakkoa have domesticated a beautiful bird species called the kaliri.\n\nI've managed to capture a young male and they appear to be trainable.  The females are much rarer, but if I had one I could attempt to breed them.  She has to be young, though... a hatchling.  An older wild bird wouldn't survive in captivity.\n\nTake this cage and travel south, to the Den of Haal'esh.  Search the nests for eggs that are ready to hatch.  If you bring me back a female hatchling, I'll reward you handsomely.", sourceObjective = "Travel to the Den of Haal'esh in Hellfire Peninsula and search the Kaliri Nests for a Female Kaliri Hatchling. Use the Empty Birdcage to capture it and bring it to Falconer Drenna Riverwind at Falcon Watch.", progress = "You've returned.  Did you bring me the kaliri female?", completion = "You did it!  You caught a female hatchling!\n\nShe's precious.  You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9398] = { id = 9398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadly Predators", description = "The Broken that live in Outland have endured endless violence.  It is of little surprise that as soon as the Dark Portal opened they flocked to it in droves with hopes of escaping this land.\n\nUnfortunately for our confused brothers and sisters coming from the south, the rock flayers that inhabit the Great Fissure see them as easy prey.  Go there and thin the rock flayer population, so that our kin might have a chance.", sourceObjective = "Scout Vanura at the Temple of Telhamat in Hellfire Peninsula wants you to slay 8 Stonescythe Whelps and 4 Stonescythe Alpha.", completion = "You've done well, {name}.  It is always unfortunate to have to resort to taking a life, even when it's that of a dangerous beast such as the rock flayer.\n\nYou have my thanks for carrying out this grim task.", sourceObjectiveStatus = "unverified-source-field" }
quests[9399] = { id = 9399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruel Taskmasters", description = "You probably think most Broken are evil, don't you?  In reality many just lack guidance.\n\nBefore I met the Omenai, I too was lost.\n\nOur minds suffered terrible pain from the orcs' demonic magic.  We are easily confused and taken advantage of.\n\nDemons allied with Illidan raid Hellfire daily and capture our kind as slaves.  With the Omenai we now have hope.  Travel to the Ruins of Sha'naar, southwest of here, and slay the Illidari taskmasters so my people may be free!", sourceObjective = "Slay 4 Illidari Taskmasters at the Ruins of Sha'naar and return to Ikan at the Temple of Telhamat in Hellfire Peninsula.", completion = "You did it!  I'm in your debt, {name}.  Look at all the Dreghoods that are showing up.\n\nUnder my guidance they'll learn all about the old ways, you'll see.", sourceObjectiveStatus = "unverified-source-field" }
quests[9400] = { id = 9400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assassin", description = "{name}, we recently uncovered a plot to assassinate our envoy to Falcon Watch.  Hellfire Citadel learned of our plans to send an expedition there earlier this morning and set up an ambush.\n\nOur scouts have informed me that an assassin known as Krun Spinebreaker waits along the road north of the Citadel.  Go there and slay this assassin.  Show the fel orcs we're not to be trifled with!", sourceObjective = "Nazgrel wants you to travel to the road north of Hellfire Citadel and look for an assassin named Krun Spinebreaker.", completion = "The corpse matches the description of Krun Spinebreaker, Hellfire Citadel's assassin.  As you turn the body over, you notice a stone axe protruding from his back.", sourceObjectiveStatus = "unverified-source-field" }
quests[9401] = { id = 9401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Weapon", description = "You pull the stone axe out of the body to examine it more closely.  There's something unusual about the craftsmanship of the weapon.\n\nIts origin appears orcish, though the materials aren't like anything you've seen before.  Nazgrel might be interested in seeing the weapon.", sourceObjective = "Bring the Heavy Stone Axe to Nazgrel in Thrallmar in Hellfire Peninsula.", progress = "Tell me, is the assassin dead?", completion = "He was killed by this weapon?  It can't be!\n\nHave we... found them?", sourceObjectiveStatus = "unverified-source-field" }
quests[9402] = { id = 9402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fetch!", description = "So... {name} is it?  Don't be flattered I know your name, one of my students has been fawning over you and won't shut up.\n\nHmm... if you'd like to impress <her/him>, why don't you do something for me?  There's an azure phial at the bottom of the pond behind me.  Dive in, retrieve it, and bring it here.", sourceObjective = "Dive to the bottom of Stillwhisper Pond and retrieve the Azure Phial for Instructor Antheol.", sourceObjectiveStatus = "unverified-source-field" }
quests[9403] = { id = 9403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purest Water", description = "Now that you've learned a little lesson, I'll offer you something more substantial.  It concerns your ability to defend yourself in close combat.  Of course, you should only resort to melee in the most dire of circumstances, but that is no excuse to be unprepared.\n\nI can assist you in creating a staff befitting a mage of your learning.  Simply take the phial you retrieved for me and fill it at the base of Elrendar Falls.  Just follow the river southeast from here.", sourceObjective = "Instructor Antheol wants you to fill the Azure Phial at Elrendar Falls.", progress = "Only water from the Elrendar Falls has the purity required for use with magic.  Do you have it?", completion = "Let's see what you've brought me...\n\n<He holds the phial up to the light and examines it closely.>\n\nYes, this will do.  Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9404] = { id = 9404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recently Living", description = "You may have noticed the walking trees near Elrendar Falls.  As the keepers of nature, they are infused with a primal magic we can reform to our own purposes using the pure water you have already brought to me.\n\nUnfortunately, the green keepers are gnarled and twisted creatures, so you may need to kill a few before you find a useable branch.", sourceObjective = "Slay the Eversong Green Keepers until they yield a Living Branch for Instructor Antheol.", progress = "Do you have the living branch?  Hand it over quickly!", completion = "You've done as I've asked, {name}, and you may take your reward now.", sourceObjectiveStatus = "unverified-source-field" }
quests[9405] = { id = 9405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief's Mandate", description = "As you know, the warchief put his power behind this expedition for one reason.  This is the world we came from.  This is where our roots lie.\n\nThis journey means different things to orcs and blood elves.  To them it's a search for the promised land.  To us it's more like returning home.\n\nWhoever made this axe is familiar with the old ways and we must contact them.  This is too important for us to use ordinary tracking methods.  Show the weapon to Far Seer Regulkut; she will know what to do.", sourceObjective = "Bring the Heavy Stone Axe to Far Seer Regulkut at Thrallmar in Hellfire Peninsula.", progress = "Tell me what you seek, so that I may help you find it.", completion = "I understand Nazgrel's request, {class}.  Say no more.", sourceObjectiveStatus = "unverified-source-field" }
quests[9406] = { id = 9406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mag'har", description = "This news you bring from beyond the Dark Portal...  you want us to believe the son of Durotan now rules over the lands beyond it... free from any demonic taint?  And that now his people have returned to this world?\n\nI hope for your sake that this isn't some manner of joke, {class}.  What this means to my people... cannot be described.  I must send word to Nagrand at once!  Hellscream must hear about this.\n\nTake this letter back to your leader in Thrallmar.  Tell him the Mag'har welcome them!", sourceObjective = "Deliver the Letter from the Mag'har to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "What do you bring us, {name}?", completion = "You're certain of this?  True orcs... here in Hellfire!  This is big news, {name}.\n\nWe must inform the warchief at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[9407] = { id = 9407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Dark Portal", description = "For years the Dark Portal loomed silent... forgotten.  But it is silent no longer.\n\nAfter stopping the demonic assault here, our forces breached the portal and met the demons on their own ground!\n\nNow, we are locked in a savage war, and there are some who think we might not win.  So it is our duty, our grim pleasure, to battle the fiends of Outland and ensure our victory, {name}.\n\nIf you would help us, then report to Lieutenant General Orion at once. He awaits you in the Outland...", sourceObjective = "Travel through the Dark Portal and find Lieutenant General Orion. He awaits your arrival on the other side, in Outland.", completion = "Our Expedition made it safely through the Portal and set up a new base called Thrallmar. Yet as you can see, the Burning Legion moved in and cut us off from our brothers. Clearly, the demons hope to retake the Dark Portal and prevent us from gathering reinforcements from Azeroth.", sourceObjectiveStatus = "unverified-source-field" }
quests[9408] = { id = 9408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Heroes", description = "While it pains me to know that we have lost so many soldiers in our efforts to breach the portal, my heart swells with pride to know that the original expeditionary force is still alive.\n\nI can hardly believe it; but here they stand - a testament to the resolve of the Alliance.\n\nInside that keep stands one of our greatest heroes: Danath Trollbane! Seek him out, {class}. He has already met and addressed all of our soldiers. He will surely want to meet you.", sourceObjective = "Speak with Force Commander Danath Trollbane at Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9409] = { id = 9409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent Delivery!", description = "Now that you've gathered all that we need to replenish our healing crystals, I need you to deliver the vials to Zalduun, our priest.  You'll find him tending to our wounded inside the central chamber of the ship.", sourceObjective = "Deliver the Bundle of Vials to Zalduun at the Crash Site in Ammen Vale.", progress = "Hello, {class}.  What have you there? Is it for me?", completion = "Good work!  This will do nicely to replenish our depleted healing crystals.\n\nBut now that you're here, I think I have another use for you, if you're willing?", sourceObjectiveStatus = "unverified-source-field" }
quests[9410] = { id = 9410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spirit Guide", description = "Even our best tracking wolves' senses can fail them, {name}.  The spirits have a way of seeing the world differently than ours.  The being you will call forth will find the person you seek, for they'll be drawn not to their scent but their essence.\n\nGo now, {class}, take this totem with you and use it at the location you found the stone axe.", sourceObjective = "Use the Wolf Totem at the location where you found Krun Spinebreaker's body and follow the Ancestral Spirit Wolf.", progress = "You are lucky to be alive.", completion = "Who are you to walk in here unannounced?  I ordered my men to stay their hand only because Ryga sensed that the spirits were with you.  \n\nSpeak freely, but choose your words wisely.  We rarely trust strangers this close to the Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9415] = { id = 9415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Marshal Bluewall", description = "Are you Marshal Bluewall's new recruits? Of course you are.\n\nWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?\n\nNow, get going and don't dry out on the way.", sourceObjective = "Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", completion = "The Alliance needs every able body they can get. The Horde has been receiving a steady supply of reinforcements from the northern part of the continent, and it's been a struggle to keep up.\n\nLet me explain the situation to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[9416] = { id = 9416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to General Kirika", description = "You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.\n\nGet your instructions from the General. It's not my job to train you, just find you.", sourceObjective = "Speak with General Kirika at the Horde encampment near Hive'Regal.", completion = "It's good that you're here, but there's no time to waste making small talk. You need instructions, and then you need to get out there.\n\nListen up.", sourceObjectiveStatus = "unverified-source-field" }
quests[9417] = { id = 9417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arakkoa Threat", description = "The arakkoa are smart creatures... smart as any gnome you ever met.  They have this way with magic and a violent temper, however. \n\nLately they've taken to attacking Honor Hold patrols, which is why we were sent here.  See, Mirren and I are world-famous marksmen, we are!  But fowl and game are what we specialize in... not these... lightning-invoking birdmen.\n\nSo what do you say you give us a hand in this one assignment?  You'll find the Den of Haal'esh to the southwest.", sourceObjective = "Gremni Longbeard in Hellfire Peninsula wants you to slay 4 Haal'eshi Windwalkers and 6 Haal'eshi Talonguards.", progress = "You're back!  How did you do?", completion = "Great job, {name}!  I hereby proclaim you an honorary Longbeard.\n\nStick around and have a drink with us, won't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[9418] = { id = 9418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avruu's Orb", description = "<As you hold the orb closer to you, you hear a voice address you.>\n\nI sense you're not of the arakkoa, so I will attempt to barter for my freedom.  My name is Aeranas. I once ruled over the eastern winds.  The Haal'eshi mage, Avruu, trapped me inside this orb.\n\nFind the altar the arakkoa used to enslave me.  It is hidden to the southeast of the arakkoa's den.  Approach it with the orb and give it to me once I'm free.  In exchange for my liberty I'll reward you with powerful treasure!", sourceObjective = "Take Avruu's Orb to the Haal'eshi Altar southeast of the Den of Haal'esh in Hellfire Peninsula and give it to Aeranas once he's free.", progress = "The freedom I've yearned for is finally mine!", completion = "With this orb I regain my liberty.  Take your reward, mortal, so that our debt may be settled.", sourceObjectiveStatus = "unverified-source-field" }
quests[9419] = { id = 9419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouring the Desert", description = "We recently found out that the Horde has been scavenging the Silithus desert for resources, but paid them little mind. We thought it could not be worth it to station large numbers in this sweltering desert.\n\nHowever, it was discovered the importance of the resources, and now we are scrambling to catch up.\n\nIf I have your assistance, you must go into the desert and recover the silithyst and return it here.", sourceObjective = "Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", progress = "Be careful out there, but also be quick. We have no time to lose.", completion = "Thank the Light you were successful.\n\nNow if we could only have started this sooner, our need would not be so desperate. We must keep the bounty of the desert from falling into the hands of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9420] = { id = 9420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Finest Down", description = "The arakkoa at the Den of Haal'esh, south of here, breed a magnificent species of birds called kaliri.  Their feathers would fetch a bundle at the trading posts back in Azeroth.  Just think of all the ale I could buy then!\n\nTell you what, you bring me a stack of kaliri feathers and I'll give you my very own hat.  What do you say?  You'll never find a hat like this one!  Do we have a deal?", sourceObjective = "Mirren Longbeard in Hellfire Peninsula wants you to bring him 8 Kaliri Feathers from the various kaliri found in the Den of Haal'esh.", progress = "Did you bring me the kaliri feathers, {class}?", completion = "You did your part.  I guess a deal is a deal!\n\nHere you go, friend.  Treat it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[9421] = { id = 9421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaman Training", sourceObjective = "I am Firmanvaar and you are wise to seek me out.  It is my calling to provide instruction to {class}, especially those who are just beginning to learn.\n\nShamanism is only now being relearned amongst the {race}, {name}.  You are brave to follow its path as it is not popular amongst your kind.\n\nI will be here when you feel you are ready for further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[9422] = { id = 9422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouring the Desert", description = "For some time now, we have been tapping the crystal resources of the Silithus desert. The only dangers we faced were from the creatures that made this place their home and the oppressive sand and dust and heat.\n\nBut now the Alliance seems to have caught on to what we have found here. It is now a race between us to capture the natural resources, and keep them from the other.\n\nI need every set of hands that is available. I hope I have yours.", sourceObjective = "Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.", progress = "Be wary of the dangers of the desert, {name}. With the Alliance lurking in the dunes, any step could be your last.", completion = "You've done well, {name}. These resources will be added to our stockpiles, and every bit is to our gain and our enemy's loss.", sourceObjectiveStatus = "unverified-source-field" }
quests[9423] = { id = 9423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Obadei", description = "With Sedai's death confirmed, you're left with the unpleasant task of returning to Obadei with the grim news.", sourceObjective = "Return to Anchorite Obadei at the Temple of Telhamat in Hellfire Peninsula and inform him of Sedai's death.", completion = "Sedai, dear brother...\n\nThose cowardly orcs!  He was unarmed, how could they?\n\nLeave me be, {name}.  I thank you for your assistance but I wish to be alone with my thoughts now.", sourceObjectiveStatus = "unverified-source-field" }
quests[9424] = { id = 9424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makuru's Vengeance", description = "Sedai was like a brother to Makuru.   We owe him our lives and more!  They call Makuru crazy but if the Omenai are not going to do anything about his death then they're the crazy ones!\n\nMakuru doesn't have much to call his own in this world, but he will give you his only possession if you avenge Sedai.  \n\nI've seen the brown orc Mag'har grunts before, up in the hills to the northeast.  They hate us!  They don't deserve our mercy!  Go, avenge Sedai!  Bring me their ancestral beads as proof!", sourceObjective = "Makuru at the Temple of Telhamat in Hellfire Peninsula wants you to bring him 10 Mag'har Ancestral Beads.", progress = "Did you avenge Sedai for Makuru?", completion = "Yes... revenge!  You did good.\n\nYou take this now.  It was a gift from Sedai.  It only makes Makuru sad to see it.", sourceObjectiveStatus = "unverified-source-field" }
quests[9425] = { id = 9425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Tarren Mill", description = "Ah, good to see you here, {class}!  I've a task that you are perfectly suited to.\n\nAs new members of the Horde, we need to make sure that we support their efforts and help them with their problems.  That way they'll be more receptive to helping us with ours.\n\nTravel to the Forsaken town, Tarren Mill, in the Hillsbrad Foothills to the southeast.  Check in with Advisor Duskingdawn when you arrive.", sourceObjective = "Travel to Tarren Mill in the Hillsbrad Foothills and speak with Advisor Duskingdawn.", completion = "My, my!  Another of my brothers arrives to pitch in.  Good!  There is much to be done in support of our new Forsaken friends, {class}.  Ask around to see who you can help out.\n\nI know that you will support them to your utmost ability!", sourceObjectiveStatus = "unverified-source-field" }
quests[9426] = { id = 9426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pools of Aggonar", description = "Much has changed since the days when we called this land Draenor.  Parts of the land have been forever changed by the demons' taint.\n\nOne such place is known as the Pools of Aggonar.  It was once the location of our people's sacred springs.  The blood of the demon Aggonar fouled the very essence of the holy waters.  This fel blood has spawned foul beings that must be cleansed if we're ever to reclaim the pools.  Travel east of here and slay the Terrorfiends and slimes that wander the pools.", sourceObjective = "Amaan the Wise wants you to go to the Pools of Aggonar and slay 6 Terrorfiends and 6 Blistering Rots.", progress = "Have you completed your task, {name}?", completion = "Yes, I feel the fel presence in the pools weakening.\n\nYou've done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9427] = { id = 9427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Waters", description = "I must ask that you finish what we've set in motion.  Now that the demonic influence has weakened you must take this cleansing vial and pour it at the very source of the taint - Aggonar's own corpse.\n\nYou will find the demon's bones at the northern end of the pools.  Beware, I sense that Aggonar's essence has not quite left this world.", sourceObjective = "Amaan the Wise wants you to travel to the Pools of Aggonar and use the Cleansing Vial at Aggonar's corpse. Return to him when Aggonar's essence is cleansed from the water.", progress = "You return, {name}.  Are the waters cleansed?", completion = "The essence of Aggonar lived on in the form of his foul offspring Aggonis.  With your success in defeating the demon, we can begin to work towards restoring the pools to their former purity.\n\nYou have our thanks, {name}.  Your work will have a deep impact in this world.", sourceObjectiveStatus = "unverified-source-field" }
quests[9428] = { id = 9428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Splintertree Post", description = "<The ambassador keeps her voice low as she leans in close.>\n\nYour reputation precedes you, {name}.  I want you to travel to Splintertree Post in Ashenvale.  The easiest way to get there on foot is to travel west through Durotar and the Barrens, and then turn north at the fork in the road.\n\nWhen you arrive, speak with Advisor Sunsworn.  Travel carefully; Ashenvale can be a very dangerous place!", sourceObjective = "Travel to Splintertree Post in Ashenvale and speak with Advisor Sunsworn.", completion = "The ambassador sent word ahead, so I've been expecting you.\n\nThe ambassador simply wants you to do as much as you can to help out around here.  She said something about making sure to cement our relationship with the rest of the Horde.\n\nAsk around - there are others in need of help further back in the Post.  And I hear that there's another Horde outpost called Zoram'gar Outpost on the coast all the way to the west.", sourceObjectiveStatus = "unverified-source-field" }
quests[9429] = { id = 9429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Travel to Darkshire", description = "I am told that there is a thorn in the side of the kingdom of Stormwind.  It is known as Duskwood, and it is a place that is filled with evil and the vile stench of undeath.\n\nAs we're trying to help as much as we can, I would like for you to travel southeast to the main human settlement there, named Darkshire.  Anchorite Delan will be awaiting your arrival.", sourceObjective = "Travel to Darkshire in Duskwood and speak with Anchorite Delan.", completion = "Greetings, {class}.  I trust that you're journey here was uneventful?\n\nThese poor souls are beset upon all sides by the creatures of the night.  It is our wish that you lend them what aid you can in pushing back the darkness.\n\nTravel about the town and get to know its inhabitants.  Please, {name}, help them in any way that you can.", sourceObjectiveStatus = "unverified-source-field" }
quests[9430] = { id = 9430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sha'naar Relics", description = "As I've told you before, I do not require eyes to see what others cannot.  I will not pass judgment on what you did on Makuru's behalf, yet I think you need to see beyond what your eyes show you.\n\nTravel southwest to the Ruins of Sha'naar and salvage any relics you find.  If fate wills it you will find what we need.\n\nThe meaning of my request might not be immediately apparent.  Have faith though, {name}.  Clarity comes to those with patience.", sourceObjective = "Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula wants you to travel to the Ruins of Sha'naar and retrieve 10 Sha'naar Relics.", progress = "Did you retrieve the Sha'naar relics, {name}?", completion = "You're very fortunate.  Just as I had hoped, you've found a special relic among these other ones.", sourceObjectiveStatus = "unverified-source-field" }
quests[9431] = { id = 9431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Approach", description = "What's a sin'dorei doing standing on the top of a windswept butte in Thousand Needles instead of the halls of Silvermoon?\n\nIt's simple. My brethren will no longer have me. Every copy of my treatise on natural cures for our magical addiction was burned.\n\nI can safely pursue my research here, but I am without my reagents. If you'd be willing to gather purifying earth from the thundering boulderkin near the western end of the Needles and deliver it to my associate at Whitereach Post, I'd appreciate it.", sourceObjective = "Gather 2 handfuls of Purifying Earth from Thundering Boulderkin and take them to Wizlo Bearingshiner at Whitereach Post.", progress = "Magistrix Elosai's note was a bit cryptic, but I think I understand what she wants me to do. If you have the earth she talked about, I can put it into the vessel you'll need for the moonwell water.", completion = "What? She didn't mention the moonwell? That's what she had in mind all along. I admit the whole thing's a bit wacky, but who am I to turn away a client, especially when she's the only one I've got?\n\nMaybe trying to sneak into a night elf settlement and steal water from their moonwell isn't the most prudent thing I've ever helped a customer do, but her money is as gold as anyone else's!", sourceObjectiveStatus = "unverified-source-field" }
quests[9432] = { id = 9432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Travel to Astranaar", description = "I am glad that you are here to help.  In fact, there is something that you can do.\n\nAs part of our inclusion within the Alliance, I would like for you to travel to the night elf town, Astranaar.  It is located in Ashenvale, a large forest that is south of Darkshore on the continent of Kalimdor.\n\nPlease speak with Vindicator Palais when you arrive to see if there's anything that you can do to help the inhabitants.", sourceObjective = "Travel to Astranaar in Ashenvale and speak with Vindicator Palais.", completion = "Always good to see a semi-familiar face.  You must be {name}.  Emissary Valustraa sent me word to expect you.\n\nThe people of Ashenvale need our assistance, {class}.  Speak with the citizens of Astranaar to see how you can help.", sourceObjectiveStatus = "unverified-source-field" }
quests[9433] = { id = 9433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dip in the Moonwell", description = "Stop looking at me like that! I didn't say I was going to send you to Thalanaar's moonwell out in the open with dipper and a flask!\n\nI've been, err... tinkering with a product I was transporting for a client. In fact, I've already set up a portable control console for the Robotron out near Thalanaar. You'll need to bring this control unit with you and use it in the vicinity of my concealed console.\n\nIf my client ever heard that I so much as removed Robotron from its packaging, he'd hang me by my ears!", sourceObjective = "Use the Robotron Control while standing near the Concealed Command Console hidden in a small cluster of bushes on the rim of the needle closest to Thalanaar to take command of a Robotron 3000. Pilot the robot to the western edge of Thousand Needles where the Alliance outpost of Thalanaar is located. Use the robot to collect a sample of the moonwell's water and return it to Wizlo Bearingshiner at Whitereach Post.", progress = "Did it do the job?", completion = "That worked better than I expected! Chalk up another one for good old goblin ingenuity!\n\nThe only problem is that it's hopelessly covered in dust! It's going to take me forever to get this thing cleaned up and replaced in its crate.\n\nOf course, time is the one thing I have in ample supply.", sourceObjectiveStatus = "unverified-source-field" }
quests[9434] = { id = 9434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Tonic", description = "<Wizlo retrieves the water sample from the robot and places it in a crate with the boulderkin earth and several other items.>\n\nThere you go, that's everything on Magistrix Elosai's list. Tell her that it's been a pleasure working with her and that I wish her luck in her research.", sourceObjective = "Deliver the Crate of Reagents to Magistrix Elosai at Freewind Post.", progress = "Were you and Wizlo able to gather the reagents?", completion = "Excellent, it appears everything is here. Now, all I have to do is mix everything together and give it a try. If this tonic does what my research indicates it should do, I may have discovered a way to lessen the effects of my people's magic addiction.\n\nYou're about to witness history in the making, {name}. Just think, without your help, this wouldn't have been possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[9435] = { id = 9435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Crystals", description = "If there's one great truth about Hillsbrad, it's that this region is destined to live under the shadow of war. Even something as innocuous as a cartload of stone is a target.\n\nNormally the loss of building materials is no great setback, but the most recent shipment from the Azurelode mine contained a crate of rare crystals I was eager to study. Forsaken raiders intercepted the cart and drove it northeast to a tower they're attempting to rebuild. It's imperative that we retrieve those crystals, {class}!", sourceObjective = "Retrieve the Shipment of Rare Crystals from the Forsaken and return it to Huraan in Southshore.", progress = "Were you able to retrieve the crystals from the Forsaken?", completion = "Thank the Light! From the tone of the foreman's letter, it sounded as if that box of crystals contained the only known samples from the mine. If we had lost them, {name}, we may never have seen another like them.\n\nI can't thank you enough for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[9436] = { id = 9436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodscalp Insight", description = "Well met, {class}. I've made a habit of studying the fighting techniques of the various troll tribes in my travels, and I've noticed a trend. The Bloodscalp trolls at the Tkashi Ruins and Bal'lal Ruins to the north use some of the same tactics as the Amani of the northern forests.\n\nTheir magic seems to have diverged in an interesting direction and they've used it to become the strongest tribe in the area. It could form the core of a powerful weapon against the Amani, but first I must find out more about it.", sourceObjective = "Nemeth Hawkeye at Grom'gol Base Camp wants you to bring him a Bloodscalp Totem from a Bloodscalp Shaman.", progress = "Do not fail me, {name}. If we can bend this Bloodscalp magic to our will, my people may yet eliminate the Amani threat.", completion = "Well done. Now, this is curious...\n\nThe inscription on this totem is in a language no troll could ever hope to learn, but one that is known to us. It names the bearer as an ally of a water elemental named Naias and marks him as one worthy to channel his power.\n\nThis is most unexpected, but not entirely bad, {name}. With your help, I'd like to pursue this further.", sourceObjectiveStatus = "unverified-source-field" }
quests[9437] = { id = 9437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight of the Dawn Runner", description = "The ogres here are useful for little more than crude jokes, sour ale, and bouts of headbutting. When my ship, the Dawn Runner, ran aground, those curs from Theramore made off with my cargo and last surviving crewman. I made my way here searching for help, but those good-for-nothing ogres stared blankly at me when I told them my story.\n\nI could use the help of a reliable {race} in recovering what remains of my cargo and freeing Ithania from North Point Tower, to the northeast, where they're being held.", sourceObjective = "Balandar Brightstar in Brackenwall Village wants you to reclaim the Dawn Runner Cargo and rescue his first mate Ithania from forces of Theramore at North Point Tower.", progress = "Have you freed Ithania and reclaimed my cargo from those glorified privateers?", completion = "Well done, {name}! As soon as Ithania has had time to rest and my preparations are complete, we'll depart this sodden wasteland and head back to civilization.", sourceObjectiveStatus = "unverified-source-field" }
quests[9438] = { id = 9438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to Thrall", description = "The warchief has been waiting for word of this ever since we set foot on Outland.  Now you get the honor of giving him the news of the Mag'har yourself.\n\nGo quickly, {name}.  Take this letter with you; it bears my personal seal.  There is nothing that Thrall wants to hear more than the message you bear.", sourceObjective = "Travel to Orgrimmar and give Thrall the Letter from Nazgrel.", progress = "You bring news from Outland, {class}?  Speak at once!", completion = "<You watch Thrall's jaw slacken as he begins to read the message from Nazgrel.>\n\nMy people... we must reach them.  We must reach Nagrand as soon as possible!", sourceObjectiveStatus = "unverified-source-field" }
quests[9439] = { id = 9439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unclaimed Baggage", description = "This is Kargath? Oh, dear. I expected a, a... well, some kind of settlement, some sign of civilization here in the wilderness.\n\nThere must be a mistake; surely this hovel full of uncouth, unwashed, sniggering savages can't be the headquarters of the Expeditionary Force. The loutish barbarians had the gall to laugh at me when I told them about how the Dark Iron dwarves robbed me and then disappeared into the Angor Fortress. I can count on you to help me recover my possessions and my dignity, can't I?", sourceObjective = "Retrieve the Advisor's Pack and Advisor's Rapier from their holding places in the Angor Fortress and return them to Advisor Sarophas at Kargath.", progress = "For Sunstrider's sake, don't stare at me! It's bad enough I'm forced to endure out here in my soiled clothing! After all I've been through, the last thing I need is to be gawked at. Did you manage to collect my possessions from that hole-in-the-ground those Dark Irons call a fortress?", completion = "You're a miracle worker, {name}! I tell you, I've never been so eager for a change of clothes in my life.\n\nAnd my rapier! I felt positively naked without my blade.\n\nYou are to be commended and rewarded for your efforts. Never let it be said that Sarophas failed to acknowledge the little people who've helped him along the way!", sourceObjectiveStatus = "unverified-source-field" }
quests[9440] = { id = 9440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Morsels", description = "I'm perfecting a weapon to use against the draenei and you're going to help me!\n\nThe Lost Ones are the backward cousins of the draenei, and I've been experimenting on them.  I just need you to feed some fel-tainted morsels to their captured livestock.  In turn, when they slaughter and eat the animals, they'll be cursed!  That'll show that stuffy Anchorite Avuun at the Harborage!\n\nGo now, hurry!  You'll find the Lost Ones and their caged animals to the northeast at the Fallow Sanctuary.", sourceObjective = "Feed the Fel-Tainted Morsels to the Lost Ones' captured animals. Then return the leftovers to Cersei Dusksinger at Stonard in the Swamp of Sorrows.", progress = "Did you feed their captured animals all of the morsels?  Wait!  You didn't give any to that stupid human they have out there in the cage, did you?\n\nOh, good!  That would have been a waste!", completion = "Oh, excellent! I can't wait to measure the effects from this latest batch!\n\nWell, you did an admirable job, sweetie.  Wish I could give you more than this for the entertainment you've provided, but you know how it is.  There's not much money to be made out here in the swamp.\n\nI'm sure it was worth it just for the fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[9441] = { id = 9441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envoy to the Mag'har", description = "I'd leave for Outland this very minute after hearing the news you brought.  Important matters require my attention in Durotar, however.\n\nI will arrange for a fitting tribute to be sent to the Mag'har immediately.  I will send my most trusted diplomats as well.  This will all take time... I need someone to represent us there right now.\n\nI must place my trust on you, {name}.  Go to the Mag'har Post in Hellfire and render whatever services you can to my kin.  Do not fail me, {name}.  Too much depends on this.", sourceObjective = "Thrall wants you to return to Gorkan Bloodfist at Mag'har Post in Hellfire Peninsula and offer him your services.", completion = "It means very much to us that you come to aid us in our time of need.  We'll not easily forget you nor he who sends you.\n\nYou have our thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[9442] = { id = 9442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Debilitating Sickness", description = "It is good that you've offered to aid us, {name}.  Our grunts have fallen sick from drinking contaminated water and I'm missing an ingredient to produce a healing salve.  I'm in need of a rare mushroom called drycap.\n\nOur foremost orders are to keep our location secret and not risk being spotted while looking for it, or I would go myself.  The only place in Hellfire Peninsula where drycap grows is a cave at the Great Fissure, south of here.\n\nBe extremely careful if you choose to seek it.", sourceObjective = "Earthcaller Ryga at Mag'har Post in Hellfire Peninsula wants you to bring her 1 Drycap Mushroom from a cave inside the Great Fissure.", progress = "Did you obtain the mushroom I need, {name}?", completion = "Gorkan said good things about you.  They're all turning out to be true.\n\nThanks for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[9443] = { id = 9443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The So-Called Mark of the Lightbringer", description = "I was once a pupil of Uther Lightbringer, founder of the Knights of the Silver Hand. I saw how he mishandled Prince Arthas's training. It led to the destruction of my homeland, Quel'Thalas, and I blame Uther and his incompetence for all of it! And now he has a tomb in his honor - how lovely.\n\nMy sources tell me that the scarlet fools are keeping one of his 'holy' relics atop their guard tower near the gates of Hearthglen.\n\nGo to the Western Plaguelands and retrieve it for me.", sourceObjective = "Obtain the Mark of the Lightbringer and return it to Mehlar Dawnblade at the Bulwark in the Western Plaguelands.", progress = "When you've managed to retrieve his 'mark', we're going to change it a bit; make it better.", completion = "The first step is complete. Hand me the Mark of the Lightbringer and I will transform it into something more suitable.\n\nThen my revenge will begin in earnest, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9444] = { id = 9444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defiling Uther's Tomb", description = "There, that's better.  I've added a little fel magic to it.\n\nNow, you must take it to his resting place in the Western Plaguelands.  Use the corrupted holy symbol in the presence of Uther's statue to defile his tomb!  You'll have to get close for it to work.\n\nTo find the tomb go southeast of the Ruins of Andorhal.  Return to me when the deed is done.\n\nBe quick about it, {class}!", sourceObjective = "Defile Uther's Tomb and return to Mehlar Dawnblade at the Bulwark in the Western Plaguelands.", progress = "It is done, then?  Uther's Tomb is defiled?", completion = "Forgives me?  He FORGIVES ME?!!!\n\nI don't care what that old ghost had to say - it was his fault!  Everything that's happened to Quel'Thalas was a result of his incompetence!\n\nIt is clear that the defiling did not work.  Go, be gone from my sight!  I must think this through.", sourceObjectiveStatus = "unverified-source-field" }
quests[9446] = { id = 9446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomb of the Lightbringer", description = "Now that you've recovered the Mark of the Lightbringer, all that is left is to return it to Uther's Tomb.\n\nWould you be willing to accompany me there to do this?  It's not far and I would enjoy your company.  Afterward you can come back here and relate the experience to High Priestess MacDonnell.\n\nWhat say you, {name}?", sourceObjective = "Escort Anchorite Truuen to Uther's Tomb in the Western Plaguelands. Afterward, speak with High Priestess MacDonnell at Chillwind Camp in the Western Plaguelands.", progress = "Aren't you supposed to be walking to Uther's Tomb with Anchorite Truuen?", completion = "The Lightbringer appeared before you?  That is amazing!  And you made it all possible through your selfless help to the anchorite.\n\nIf even half of the stories are to be believed, Uther was a great man.  And, like him, you are a true hero to all of the good people of Azeroth, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9447] = { id = 9447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Administering the Salve", description = "I've prepared a simple salve that should restore our grunts' strength with the herbs you brought me.  Take it and administer it to any debilitated grunts you see in the vicinity.  Return to me when you're done.", sourceObjective = "Earthcaller Ryga wants you to administer the Healing Salve to 10 Debilitated Mag'har Grunts nearby Mag'har Post in Hellfire Peninsula.", progress = "You've returned, {name}.  Is your task complete?", completion = "May the spirits bless you, {name}.  The Mag'har are in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9448] = { id = 9448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercy for the Cursed", description = "That blood elf witch, Cersei Dusksinger, has been cursing the Lost Ones, I just know it!  I don't know why or how, but the results are tragic.  Several of the Lost Ones have now been further corrupted - cursed with even more fel energies!\n\n{class}, can you find it in you to take pity on these poor creatures?  They should not have to live out the rest of their lives in such a horrible condition.\n\nYou'll find these cursed Lost Ones at the Fallow Sanctuary, east down the path.", sourceObjective = "Slay 3 Cursed Lost Ones and then return to Anchorite Avuun at the Harborage in the Swamp of Sorrows.", progress = "You are doing the right thing, {class}.  The Lost Ones have suffered so much already.  They shouldn't have to suffer this further indignity.", completion = "It is done then.  I thank you for showing your compassion.  Once corrupted by whatever Cersei was feeding them, there is nothing else that could be done.\n\nThey are now at peace and hopefully my studies of the others will bear fruit so that they can be rehabilitated.", sourceObjectiveStatus = "unverified-source-field" }
quests[9449] = { id = 9449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "The time has come, {name}.  You have grown to the point where you are ready to commune directly with the elemental spirits of this world.\n\nBut be warned.  I can sense that the manner of our entry into this world, and its unfortunate side effects, have angered the earth spirits and caused an imbalance of the elements.\n\nIf you are to create your earth totem, you must first speak with the Spirit of the Vale.  You will find it in the Sacred Grove, nestled in the hills to the northwest.", sourceObjective = "Speak with the Spirit of the Vale at the Sacred Grove in Ammen Vale.", completion = "You are bold to seek my wisdom after what your people have done to these islands, stranger!  Still, there is much to be said for your bravery, so I will impart to you some knowledge.\n\nThe earth beneath your feet forms the foundation for all things.  The sky, the waters, even great fire - all rest upon its shoulders.  While those others often form chaotic tempests, the earth abides.  It grants strength and fortitude to the core of your being.\n\nNow you will prove yourself, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9450] = { id = 9450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "The balance of the elements has been disrupted by the violent intrusion of the draenei to the Vale.  Your crash has caused the spirits of earth to be enraged and turn upon the other elements who have come to quell them.  You will learn that an understanding of the elements can only come when all are in harmony.\n\nThus, it falls to you to seek a balance.  Behind me in the grove you will find the restless spirits of earth warring upon the other three elements.  Help restore the balance.", sourceObjective = "Slay 4 Restless Elements of Earth and then return to the Spirit of the Vale at the Sacred Grove in Ammen Vale.", progress = "The elements still seem out of balance to me, {name}.", completion = "You have done well.  By thinning out the restless spirits you have helped to heal the imbalance between the elements, which your people inadvertently caused.\n\nThroughout your journey as a {class} you must keep this in mind when calling upon our power.  The balance must be preserved.", sourceObjectiveStatus = "unverified-source-field" }
quests[9451] = { id = 9451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "I will now give you a piece of my physical being that you may create your earth totem.  Return it to he who sent you here.\n\nYou and I will be bound together for all time.  Throughout your life the forces of earth will be at your disposal.  The balance will come when your bones return to us at the end of your days.\n\nUse our power wisely.", sourceObjective = "Deliver the Earth Crystal to Firmanvaar at the Crash Site in Ammen Vale.", progress = "Together, the Broken and the {race} will regain a deeper understanding of the mysteries that the elements hold.\n\nHave you returned with that which is necessary for the creation of your earth totem?", completion = "You have done well, {name}.  In helping to restore the balance of the elements at the grove, you have also created a balance between the earth element of this world and the {race}.  Perhaps this will help to bring understanding to those amongst us who do not approve of our ways?\n\nI will create for you a totem through which you will be able to call on the power of earth to do your bidding.  And with time, more of the mysteries of earth will be revealed to you.\n\nNow, take your totem, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9452] = { id = 9452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Snapper - Very Tasty!", description = "I've found that these waters are bustling with red snapper, a very tasty fish. With a fishing net, I can catch enough to feed dozens of draenei! Unfortunately, I was recently attacked by a creature known as a murloc while netting in the river and have suffered some injuries that prevent me from doing my job. I need help!\n\nUse this fishing net near schools of red snapper, found in the Crystalbrook river to the east to catch the fish.\n\nWhat do you say? Remember to return the net when you are finished.", sourceObjective = "Use the Draenei Fishing Net to catch 10 Red Snappers. Return both the fish and the net to Diktynna on Azuremyst Isle when the task is complete.", progress = "Watch out for murlocs: Strange and extremely annoying little creatures.", completion = "I hope the murlocs didn't cause too much trouble, {name}. I owe you a great debt of gratitude for all that you've done.\n\nPerhaps I could teach you how to fish? I'll even supply the fishing pole and a bauble.", sourceObjectiveStatus = "unverified-source-field" }
quests[9453] = { id = 9453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Acteon!", description = "You did a wonderful job, {name}. Our people will be thankful for this bounty. With that said, would you mind taking this haul of red snapper to Acteon at Azure Watch?\n\nHe shouldn't be hard to find as he is awaiting this catch.", sourceObjective = "Deliver the Crate of Red Snapper to Acteon at Azure Watch.", progress = "What do you think of my armor? Crafted it myself! It's a little different than what we'd traditionally wear but extremely comfortable.", completion = "Poor Diktynna... That murloc gave her quite a scare.\n\n<Acteon sighs.>\n\nHopefully she will recover from the injuries soon...\n\nSo I presume you're looking for work. Well there's plenty of that to be found at Azure Watch!", sourceObjectiveStatus = "unverified-source-field" }
quests[9454] = { id = 9454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Moongraze Hunt", description = "You're starting to make a name for yourself, {name}. How about trying your hand at hunting?\n\nBack on Draenor, our greatest hunters would hunt a beast that resembled the moongraze stag of this region known as a talbuk.\n\nIf you think yourself draenei enough, go out into the wilds and kill enough stags to fill your pack with meat.\n\nYou will find them grazing south of Azure Watch. Watch out for their horns!", sourceObjective = "Bring 6 Moongraze Stag Tenderloins to Acteon at Azure Watch.", progress = "The stag hides are frail which tend to make for tender, succulent flesh.", completion = "Well done, {name}, well done!\n\nHere, I cooked up some tenderloins while you were gone. Maybe you'd like the recipe, too?", sourceObjectiveStatus = "unverified-source-field" }
quests[9455] = { id = 9455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Findings", description = "The crystal you found on the nightstalker runt's body appears to be a piece of the Exodar. This may help explain the unusual appearance and demeanor of some of the animals in this region.\n\nTake the crystal back to Azure Watch. The exarch will surely want to know about this discovery.", sourceObjective = "Deliver the Faintly Glowing Crystal to Exarch Menelaous at Azure Watch.", progress = "You found what? Where?", completion = "How did such a thing end up in the stomach of a nightstalker? Could the debris from the crash have contaminated more beasts?", sourceObjectiveStatus = "unverified-source-field" }
quests[9456] = { id = 9456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightstalker Clean Up, Isle 2...", description = "I'm not going to make any excuses for what you've found. This is clearly our fault. We had gotten reports of crushed crystal fragments showing up in the river to the east but chose to ignore the implications. Now we can either sit around on this island and cry about the tragedy that has befallen this land or we can do something about it and prevent it from spreading.\n\nIf you've got the stomach for it, I want you to go back into the wilds and kill as many of the infected nightstalkers as you can find.", sourceObjective = "Exarch Menelaous at Azure Watch has asked that you slay 8 Infected Nightstalker Runts.", progress = "We can't risk this contamination spreading. The reports I've heard come from Blood Watch are bad enough. This has to be stopped now!", completion = "I just hope it's not too late...", sourceObjectiveStatus = "unverified-source-field" }
quests[9457] = { id = 9457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unusual Patron", description = "So this Naias is the mastermind behind the Bloodscalp and their exotic magic? I'll admit, this is the last place I expected my inquiry to lead, but no matter, our findings may still prove useful.\n\nOff the coast to the northwest is an island inhabited by lesser water elementals. There's a crude stone slab there that might serve as an altar for the likes of the trolls. Take the totem you found to that altar. Let's see if we can draw this Naias out and distill his power into a more agreeable form.", sourceObjective = "Use the Gift of Naias near the Altar of Naias to summon the water elemental Naias. Defeat him and return to Nemeth Hawkeye at Grom'gol Base Camp with the Heart of Naias.", progress = "What news of Naias, {name}?", completion = "I can feel the raw power contained in this gem, {name}. I'll send it to Silvermoon for our magisters to study further, but I am sure it will prove useful in our struggle against the Amani.\n\nYour help has been invaluable in procuring this gem, and I will see to it that the Farstriders know the name of the {race} who made this find possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[9460] = { id = 9460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combining Forces", description = "Keltus Darkleaf reporting for duty!\n\nOh... who are you, anyhow?  If you are here for my report, I insist you help me first.\n\nI am planning to attack the sentinel spies, but I intend to send in my faithful Whisper as a first strike.  She just needs a scent to hone in on them.\n\nSurely someone of your skill could sneak in and steal something from the sentinel leader?", sourceObjective = "Keltus Darkleaf wants you to pickpocket the Lacy Handkerchief from the Sentinel Leader and bring it to him.", progress = "Did you get something?", completion = "Excellent!  Such a personal item carries a strong scent of the intruders--enough to guide Whisper into their ranks...", sourceObjectiveStatus = "unverified-source-field" }
quests[9461] = { id = 9461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "You should know that The Prophet has been asking for you, having heard of your success in your trial. The creation of your fire totem will have to wait until you have spoken with him.\n\nThis is a rare honor; you must hurry to the Exodar to see him at once!", sourceObjective = "Seek out Prophet Velen at the Vault of Lights in the Exodar.", completion = "Hello, {name}, I have been expecting you.  I trust this day finds you well?", sourceObjectiveStatus = "unverified-source-field" }
